/* PsychLogic — Full-Length Mock 11. Question bank. */
window.MOCK_QUESTIONS = [{"id": 1, "question": "The primary visual cortex is located in which lobe of the brain?", "options": ["Frontal lobe", "Occipital lobe", "Parietal lobe", "Temporal lobe"], "correctAnswer": 1, "subject": "Biological Psychology & Neuropsychology", "subtopic": "", "difficulty": "", "explanation": "<p>Occipital lobe</p><p class=\"ex-why\"><b>Why:</b> The primary visual cortex (V1, Brodmann area 17, also called striate cortex) lies in the occipital lobe at the back of the brain, around the calcarine sulcus. Damage here causes loss of vision in the opposite visual field.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Frontal lobe — The frontal lobe handles movement, planning and executive control.</li><li>(C) Parietal lobe — The parietal lobe handles touch, body sense and spatial attention.</li><li>(D) Temporal lobe — The temporal lobe handles hearing, language comprehension and memory.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Primary auditory cortex = temporal lobe (Heschl’s gyrus); primary somatosensory = parietal (postcentral gyrus); primary motor = frontal (precentral gyrus).</li><li>Bilateral occipital damage can cause cortical blindness (Anton’s syndrome if denied).</li></ul>", "examWatch": "This is an actual previous-year question. Examiners do repeat questions, sometimes word for word — make sure you can answer it instantly."}, {"id": 2, "question": "According to Masters and Johnson, the correct order of the human sexual response cycle is:", "options": ["Excitement → Orgasm → Plateau → Resolution", "Excitement → Plateau → Orgasm → Resolution", "Excitement → Arousal → Orgasm → Resolution", "Arousal → Excitement → Orgasm → Resolution"], "correctAnswer": 1, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Excitement → Plateau → Orgasm → Resolution</p><p class=\"ex-why\"><b>Why:</b> Masters and Johnson (Human Sexual Response, 1966) described four phases from laboratory observation: Excitement → Plateau → Orgasm → Resolution.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Excitement → Orgasm → Plateau → Resolution — Plateau comes before orgasm, not after it.</li><li>(C) Excitement → Arousal → Orgasm → Resolution — ‘Arousal’ is not a separate phase in their model; it is part of excitement.</li><li>(D) Arousal → Excitement → Orgasm → Resolution — Their model starts with excitement; ‘arousal’ is not listed first.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Helen Singer Kaplan added a ‘Desire’ phase, giving a triphasic model (desire, excitement, orgasm).</li><li>Rosemary Basson proposed a circular (non-linear) model of female sexual response.</li></ul>", "examWatch": "A real past-paper question. Repeats are common, so learn it exactly as it is."}, {"id": 3, "question": "Perception in the absence of any sensory stimulus is called:", "options": ["Illusion", "Hallucination", "Phenomenon", "Perceptual constancy"], "correctAnswer": 1, "subject": "Core Psychological Processes", "subtopic": "", "difficulty": "", "explanation": "<p>Hallucination</p><p class=\"ex-why\"><b>Why:</b> A hallucination is a perception without any external stimulus that feels as real as a normal perception, e.g. hearing voices when no one is speaking.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Illusion — An illusion is a misperception of a real external stimulus (e.g. a rope seen as a snake).</li><li>(C) Phenomenon — ‘Phenomenon’ is a general word, not a clinical term for this.</li><li>(D) Perceptual constancy — Perceptual constancy is seeing objects as stable despite changes in the image (size, shape, colour).</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Pseudohallucinations are experienced in inner subjective space and recognised as unreal.</li><li>Hypnagogic hallucinations occur while falling asleep; hypnopompic while waking up.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this exact question has come before. Make sure you never lose this mark."}, {"id": 4, "question": "Following a road accident, Amit becomes impulsive, irresponsible and unconcerned about the consequences of his actions. Which brain region is most likely damaged?", "options": ["Parietal lobe", "Frontal lobe", "Occipital lobe", "Temporal lobe"], "correctAnswer": 1, "subject": "Biological Psychology & Neuropsychology", "subtopic": "", "difficulty": "", "explanation": "<p>Frontal lobe</p><p class=\"ex-why\"><b>Why:</b> Impulsivity, irresponsibility and lack of concern for consequences after head injury point to frontal lobe damage, especially the orbitofrontal cortex — the classic ‘Phineas Gage’ picture.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Parietal lobe — Parietal damage causes sensory and spatial problems such as neglect.</li><li>(C) Occipital lobe — Occipital damage affects vision.</li><li>(D) Temporal lobe — Temporal damage affects memory, hearing and language comprehension.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Three frontal syndromes: dorsolateral (dysexecutive), orbitofrontal (disinhibited), medial (apathetic).</li><li>Phineas Gage (1848) was described by John Harlow.</li></ul>", "examWatch": "This is an actual previous-year question. Examiners do repeat questions, sometimes word for word — make sure you can answer it instantly."}, {"id": 5, "question": "Match the author (List I) with the book (List II): List I: (i) Thomas Szasz   (ii) Michel Foucault   (iii) Erich Fromm   (iv) Sigmund Freud List II: (P) Madness and Civilization   (Q) The Myth of Mental Illness   (R) Escape from Freedom   (S) Moses and Monotheism", "options": ["i-P, ii-Q, iii-R, iv-S", "i-Q, ii-P, iii-S, iv-R", "i-Q, ii-R, iii-P, iv-S", "i-Q, ii-P, iii-R, iv-S"], "correctAnswer": 3, "subject": "Therapies & Interventions", "subtopic": "", "difficulty": "", "explanation": "<p>i-Q, ii-P, iii-R, iv-S</p><p class=\"ex-why\"><b>Why:</b> Thomas Szasz – The Myth of Mental Illness (1961); Michel Foucault – Madness and Civilization (1961); Erich Fromm – Escape from Freedom (1941); Sigmund Freud – Moses and Monotheism (1939).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) i-P, ii-Q, iii-R, iv-S — Option A gives Szasz and Foucault the wrong books.</li><li>(B) i-Q, ii-P, iii-S, iv-R — Option B swaps Fromm’s and Freud’s books.</li><li>(C) i-Q, ii-R, iii-P, iv-S — Option C swaps Foucault and Fromm.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Szasz argued that ‘mental illness’ is a metaphor for problems in living (anti-psychiatry).</li><li>R.D. Laing (The Divided Self, 1960) is another anti-psychiatry figure.</li></ul>", "examWatch": "This area has appeared in previous papers. It may well come in your exam too."}, {"id": 6, "question": "Down syndrome (formerly called &quot;Mongolism&quot;) results from:", "options": ["An extra chromosome on pair 23", "An extra chromosome on pair 21", "An extra chromosome on pair 20", "An extra Y chromosome"], "correctAnswer": 1, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>An extra chromosome on pair 21</p><p class=\"ex-why\"><b>Why:</b> Down syndrome is most commonly caused by trisomy 21 — an extra copy of chromosome 21, usually from non-disjunction during egg formation. Risk rises with maternal age.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) An extra chromosome on pair 23 — Pair 23 is the sex chromosomes; extra sex chromosomes cause conditions such as Klinefelter (XXY).</li><li>(C) An extra chromosome on pair 20 — Trisomy of chromosome 20 is not Down syndrome.</li><li>(D) An extra Y chromosome — An extra Y (XYY) gives Jacobs syndrome.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Other forms of Down syndrome: translocation and mosaicism.</li><li>Chromosome 21 carries the APP gene, so adults with Down syndrome get Alzheimer’s disease early.</li></ul>", "examWatch": "A real past-paper question. Repeats are common, so learn it exactly as it is."}, {"id": 7, "question": "The myelin sheath primarily serves to:", "options": ["Insulate nerve fibers from one another", "Carry neural message", "Act as energy center", "Receive incoming information"], "correctAnswer": 0, "subject": "Biological Psychology & Neuropsychology", "subtopic": "", "difficulty": "", "explanation": "<p>Insulate nerve fibers from one another</p><p class=\"ex-why\"><b>Why:</b> Myelin, made by Schwann cells (PNS) and oligodendrocytes (CNS), wraps axons and insulates them. This also speeds conduction, because the impulse jumps from one node of Ranvier to the next (saltatory conduction).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Carry neural message — The axon itself carries the neural message; myelin only insulates it.</li><li>(C) Act as energy center — Mitochondria are the energy centres of the cell.</li><li>(D) Receive incoming information — Dendrites receive incoming information.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Multiple sclerosis is an autoimmune loss of CNS myelin.</li><li>Guillain–Barré syndrome affects peripheral myelin.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this exact question has come before. Make sure you never lose this mark."}, {"id": 8, "question": "Non-fluent, effortful speech with relatively preserved comprehension suggests damage to:", "options": ["Wernicke's area", "Angular gyrus", "Primary auditory cortex", "Broca's area"], "correctAnswer": 3, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Broca&#x27;s area</p><p class=\"ex-why\"><b>Why:</b> Slow, effortful, non-fluent (telegraphic) speech with fairly good comprehension is Broca’s (expressive) aphasia, from damage to the left inferior frontal gyrus (Brodmann areas 44 and 45).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Wernicke&#x27;s area — Wernicke’s area damage gives fluent but meaningless speech with poor comprehension.</li><li>(B) Angular gyrus — Angular gyrus damage gives alexia with agraphia or Gerstmann syndrome.</li><li>(C) Primary auditory cortex — Primary auditory cortex damage affects hearing of sounds, not speech production.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Broca described his patient ‘Tan’ in 1861.</li><li>Repetition is poor in Broca’s aphasia but preserved in transcortical motor aphasia.</li></ul>", "examWatch": "Not asked directly yet, but it sits right next to frequently asked topics — it may appear in a new form."}, {"id": 9, "question": "Degeneration of dopamine-producing neurons in the substantia nigra characterises which neurological disorder?", "options": ["Alzheimer's disease", "Parkinson's disease", "Multiple sclerosis", "Epilepsy"], "correctAnswer": 1, "subject": "Biological Psychology & Neuropsychology", "subtopic": "", "difficulty": "", "explanation": "<p>Parkinson&#x27;s disease</p><p class=\"ex-why\"><b>Why:</b> Parkinson’s disease results from the loss of dopamine neurons in the substantia nigra pars compacta. The main signs are bradykinesia, resting tremor, rigidity and postural instability.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Alzheimer&#x27;s disease — Alzheimer’s disease involves amyloid plaques, tangles and loss of acetylcholine neurons.</li><li>(C) Multiple sclerosis — Multiple sclerosis is a demyelinating disease.</li><li>(D) Epilepsy — Epilepsy involves recurrent seizures from abnormal electrical discharges.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>L-dopa is the main drug, as dopamine itself cannot cross the blood–brain barrier.</li><li>Huntington’s disease affects the caudate nucleus (GABA neurons).</li></ul>", "examWatch": "This is an actual previous-year question. Examiners do repeat questions, sometimes word for word — make sure you can answer it instantly."}, {"id": 10, "question": "Which structure connects the left hemisphere with the right hemisphere?", "options": ["Corpus callosum", "Inferior colliculi", "Wernicke's area", "Broca's area"], "correctAnswer": 0, "subject": "Biological Psychology & Neuropsychology", "subtopic": "", "difficulty": "", "explanation": "<p>Corpus callosum</p><p class=\"ex-why\"><b>Why:</b> The corpus callosum is the largest bundle of fibres linking the left and right cerebral hemispheres. Cutting it (split-brain surgery) was used to control severe epilepsy.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Inferior colliculi — The inferior colliculi are midbrain auditory relay centres.</li><li>(C) Wernicke&#x27;s area — Wernicke’s area is a language comprehension area in one hemisphere.</li><li>(D) Broca&#x27;s area — Broca’s area is a speech production area in one hemisphere.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Sperry and Gazzaniga studied split-brain patients (Nobel Prize to Sperry, 1981).</li><li>The anterior commissure is a smaller link between the hemispheres.</li></ul>", "examWatch": "A real past-paper question. Repeats are common, so learn it exactly as it is."}, {"id": 11, "question": "A 40-year-old man sustains a road-traffic injury and a few days later has difficulty executing plans. He has most likely injured the:", "options": ["Inferior Frontal Cortex", "Dorsolateral Prefrontal Cortex", "Orbitofrontal Cortex", "Medial Prefrontal Cortex"], "correctAnswer": 1, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Dorsolateral Prefrontal Cortex</p><p class=\"ex-why\"><b>Why:</b> Difficulty planning and carrying out plans (executive dysfunction) points to the dorsolateral prefrontal cortex, which supports planning, working memory and set-shifting.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Inferior Frontal Cortex — The inferior frontal cortex (left) is linked mainly with speech (Broca’s area) and response inhibition.</li><li>(C) Orbitofrontal Cortex — Orbitofrontal damage mainly causes disinhibition and poor social judgement.</li><li>(D) Medial Prefrontal Cortex — Medial prefrontal damage mainly causes apathy and reduced initiative.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Tests of DLPFC function: WCST, Tower of London, verbal fluency, Trail Making B.</li><li>Working memory is closely linked to the DLPFC.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this exact question has come before. Make sure you never lose this mark."}, {"id": 12, "question": "Excessive perseverative errors on the Wisconsin Card Sorting Test most strongly suggest dysfunction of the:", "options": ["Occipital cortex", "Cerebellar vermis", "Dorsolateral prefrontal cortex", "Hippocampus"], "correctAnswer": 2, "subject": "Assessment & Psychometrics", "subtopic": "", "difficulty": "", "explanation": "<p>Dorsolateral prefrontal cortex</p><p class=\"ex-why\"><b>Why:</b> The WCST asks the person to find a sorting rule from feedback and to switch when the rule changes. Perseverative errors (sticking to an old rule) are the classic sign of dorsolateral prefrontal dysfunction.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Occipital cortex — The occipital cortex handles vision, not rule-switching.</li><li>(B) Cerebellar vermis — The cerebellar vermis affects balance and gait.</li><li>(D) Hippocampus — The hippocampus supports new memories, not set-shifting.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>WCST was developed by Grant and Berg (1948).</li><li>Main scores: categories completed and perseverative errors.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a likely new area. Learn the key points above."}, {"id": 13, "question": "In REM sleep behaviour disorder, patients act out their dreams. Which normal feature of REM sleep is absent in them?", "options": ["Atonia", "Rapid eye movements", "High frequency, low amplitude EEG", "Penile erections (in males)"], "correctAnswer": 0, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Atonia</p><p class=\"ex-why\"><b>Why:</b> Normal REM sleep has muscle atonia (paralysis), so dreams are not acted out. In REM sleep behaviour disorder this atonia is lost, so people punch, kick or shout during dreams.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Rapid eye movements — Rapid eye movements are still present.</li><li>(C) High frequency, low amplitude EEG — The ‘awake-like’ EEG of REM is still present.</li><li>(D) Penile erections (in males) — Erections are a normal part of REM and are not the missing feature.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>RBD often comes years before Parkinson’s disease or Lewy body dementia.</li><li>REM sleep is also called paradoxical sleep.</li></ul>", "examWatch": "This is an actual previous-year question. Examiners do repeat questions, sometimes word for word — make sure you can answer it instantly."}, {"id": 14, "question": "Sleep spindles and K-complexes are characteristic of which stage of sleep?", "options": ["NREM stage 2", "NREM stage 3", "NREM stage 1", "REM sleep"], "correctAnswer": 0, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>NREM stage 2</p><p class=\"ex-why\"><b>Why:</b> Sleep spindles (short bursts of 12–14 Hz waves) and K-complexes (large single waves) are the hallmarks of NREM stage 2 (N2), the stage in which adults spend most of the night.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) NREM stage 3 — N3 shows delta (slow) waves.</li><li>(C) NREM stage 1 — N1 shows theta waves and vertex sharp waves.</li><li>(D) REM sleep — REM shows low-voltage mixed-frequency EEG with sawtooth waves.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Order in the first cycle: N1 → N2 → N3 → REM.</li><li>Slow-wave (N3) sleep dominates the first half of the night; REM dominates the second half.</li></ul>", "examWatch": "A fresh, predicted question. The neighbouring topics are asked often, so it is worth knowing."}, {"id": 15, "question": "The body&#x27;s primary circadian pacemaker is the:", "options": ["Pineal gland", "Hippocampus", "Suprachiasmatic nucleus", "Amygdala"], "correctAnswer": 2, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Suprachiasmatic nucleus</p><p class=\"ex-why\"><b>Why:</b> The suprachiasmatic nucleus (SCN) of the hypothalamus is the body’s master clock. It receives light information from the retina and sets daily rhythms.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Pineal gland — The pineal gland releases melatonin under the SCN’s control, but it is not the pacemaker.</li><li>(B) Hippocampus — The hippocampus is for memory.</li><li>(D) Amygdala — The amygdala is for emotion and fear.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Light reaches the SCN through the retinohypothalamic tract.</li><li>Jet lag and shift-work disorder are circadian rhythm problems.</li></ul>", "examWatch": "A real past-paper question. Repeats are common, so learn it exactly as it is."}, {"id": 16, "question": "The audible range of human hearing is from 20 Hz up to approximately ______ Hz.", "options": ["200", "150000", "100", "20000"], "correctAnswer": 3, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>20000</p><p class=\"ex-why\"><b>Why:</b> Young, healthy humans hear sounds from about 20 Hz to about 20,000 Hz (20 kHz). The upper limit falls with age (presbycusis).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) 200 — 200 Hz is far too low an upper limit.</li><li>(B) 150000 — 150,000 Hz is ultrasound, beyond human hearing.</li><li>(C) 100 — 100 Hz is far too low.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Sounds below 20 Hz are infrasound; above 20 kHz, ultrasound.</li><li>Human hearing is most sensitive at about 2,000–5,000 Hz.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this exact question has come before. Make sure you never lose this mark."}, {"id": 17, "question": "Neglect of the left half of space (hemispatial neglect) typically follows a lesion of the:", "options": ["Left temporal lobe", "Right parietal lobe", "Left frontal lobe", "Right occipital lobe"], "correctAnswer": 1, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Right parietal lobe</p><p class=\"ex-why\"><b>Why:</b> Hemispatial neglect of the left side is most common and most severe after damage to the right parietal lobe (inferior parietal lobule), because the right hemisphere attends to both sides of space.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Left temporal lobe — Left temporal damage affects language and verbal memory.</li><li>(C) Left frontal lobe — Left frontal damage affects speech output and movement.</li><li>(D) Right occipital lobe — Right occipital damage causes a visual field loss, which the person knows about.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Neglect is tested with line bisection, cancellation tasks and clock drawing.</li><li>It often comes with anosognosia (unawareness of deficit).</li></ul>", "examWatch": "This angle is new, but the topic around it is popular with examiners — don’t skip it."}, {"id": 18, "question": "Prosopagnosia is most associated with damage to the:", "options": ["Hippocampus", "Caudate nucleus", "Amygdala", "Fusiform gyrus"], "correctAnswer": 3, "subject": "Biological Psychology & Neuropsychology", "subtopic": "", "difficulty": "", "explanation": "<p>Fusiform gyrus</p><p class=\"ex-why\"><b>Why:</b> Prosopagnosia (face blindness) is linked to damage of the fusiform gyrus (‘fusiform face area’) in the ventral occipito-temporal cortex, often bilateral or right-sided.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Hippocampus — The hippocampus is for forming new memories.</li><li>(B) Caudate nucleus — The caudate nucleus is part of the basal ganglia (movement, habits).</li><li>(C) Amygdala — The amygdala processes emotion, including emotional facial expressions.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>IHBAS 2024 asked what prosopagnosia makes a person unable to do (recognise faces).</li><li>Capgras delusion: the face is recognised but the feeling of familiarity is missing.</li></ul>", "examWatch": "Not asked directly yet, but it sits right next to frequently asked topics — it may appear in a new form."}, {"id": 19, "question": "Which of the following is NOT a set of opponent colours according to opponent-process theory?", "options": ["Red / blue", "Red / green", "Yellow / blue", "White / black"], "correctAnswer": 0, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Red / blue</p><p class=\"ex-why\"><b>Why:</b> Hering’s opponent-process theory proposes three opposing pairs: red–green, yellow–blue and white–black. Red–blue is not one of them.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Red / green — Red–green is an opponent pair.</li><li>(C) Yellow / blue — Yellow–blue is an opponent pair.</li><li>(D) White / black — White–black (light–dark) is an opponent pair.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Opponent processes explain negative afterimages (staring at green gives a red afterimage).</li><li>Young–Helmholtz trichromatic theory works at the receptor (cone) level.</li></ul>", "examWatch": "This is an actual previous-year question. Examiners do repeat questions, sometimes word for word — make sure you can answer it instantly."}, {"id": 20, "question": "The monoamine hypothesis of depression proposes a functional deficiency of:", "options": ["Insulin and cortisol", "GABA and glutamate", "Dopamine and acetylcholine", "Serotonin and noradrenaline"], "correctAnswer": 3, "subject": "Psychopathology, Classification & Law", "subtopic": "", "difficulty": "", "explanation": "<p>Serotonin and noradrenaline</p><p class=\"ex-why\"><b>Why:</b> The monoamine hypothesis (1960s, Schildkraut and others) proposed that depression results from a functional shortage of serotonin and noradrenaline. Antidepressants such as SSRIs and SNRIs increase these.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Insulin and cortisol — Insulin and cortisol are hormones, not monoamines.</li><li>(B) GABA and glutamate — GABA and glutamate are amino-acid neurotransmitters.</li><li>(C) Dopamine and acetylcholine — Acetylcholine is not a monoamine; dopamine is, but the classic pair is serotonin and noradrenaline.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The delay in antidepressant effect (2–6 weeks) is a major criticism of the theory.</li><li>Newer ideas include neuroplasticity (BDNF) and HPA-axis hyperactivity.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a likely new area. Learn the key points above."}, {"id": 21, "question": "Match the test (List I) with what it assesses (List II): List I: (i) Stroop Colour-Word Test   (ii) Wisconsin Card Sorting Test   (iii) MMSE   (iv) ISAA List II: (P) Severity of autism   (Q) Cognitive screening for dementia   (R) Set-shifting / executive function   (S) Selective attention (interference)", "options": ["i-R, ii-S, iii-Q, iv-P", "i-S, ii-R, iii-P, iv-Q", "i-S, ii-Q, iii-R, iv-P", "i-S, ii-R, iii-Q, iv-P"], "correctAnswer": 3, "subject": "Biological Psychology & Neuropsychology", "subtopic": "", "difficulty": "", "explanation": "<p>i-S, ii-R, iii-Q, iv-P</p><p class=\"ex-why\"><b>Why:</b> Stroop – selective attention and interference control; WCST – set-shifting and executive function; MMSE – brief cognitive screening for dementia; ISAA – Indian Scale for Assessment of Autism, which measures severity and disability.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) i-R, ii-S, iii-Q, iv-P — Option A swaps Stroop and WCST.</li><li>(B) i-S, ii-R, iii-P, iv-Q — Option B swaps MMSE and ISAA.</li><li>(C) i-S, ii-Q, iii-R, iv-P — Option C swaps WCST and MMSE.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>MMSE was developed by Folstein and colleagues (1975); maximum score 30.</li><li>ISAA was developed by the National Institute for the Mentally Handicapped (now NIEPID), Secunderabad.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this concept has been asked before in different forms — revise the related points as well."}, {"id": 22, "question": "Which gland releases insulin?", "options": ["Adrenal medulla", "Thyroid gland", "Pancreas", "Pituitary gland"], "correctAnswer": 2, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Pancreas</p><p class=\"ex-why\"><b>Why:</b> Insulin is released by the beta cells of the islets of Langerhans in the pancreas. It lowers blood sugar.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Adrenal medulla — The adrenal medulla releases adrenaline and noradrenaline.</li><li>(B) Thyroid gland — The thyroid releases thyroxine, which controls metabolism.</li><li>(D) Pituitary gland — The pituitary is the ‘master gland’ releasing trophic hormones such as ACTH and TSH.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Glucagon, from the alpha cells, raises blood sugar.</li><li>Diabetes mellitus involves insulin shortage or resistance.</li></ul>", "examWatch": "A real past-paper question. Repeats are common, so learn it exactly as it is."}, {"id": 23, "question": "A music student learnt raag Malkauns and, a month later, raag Kaafi. Whenever he tries to sing Kaafi he slips into Malkauns. This is known as:", "options": ["The method of loci", "Forgetting curve", "Proactive interference", "Retroactive interference"], "correctAnswer": 2, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Proactive interference</p><p class=\"ex-why\"><b>Why:</b> In proactive interference, old learning (raag Malkauns) disrupts the recall of newer learning (raag Kaafi). ‘Pro’ = forward in time.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) The method of loci — The method of loci is a memory aid using places along a route.</li><li>(B) Forgetting curve — The forgetting curve (Ebbinghaus) describes fast loss of memory over time.</li><li>(D) Retroactive interference — In retroactive interference, new learning disrupts older memories — the reverse.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Ebbinghaus used nonsense syllables to study forgetting (1885).</li><li>Interference theory and decay theory are the two classic theories of forgetting.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this exact question has come before. Make sure you never lose this mark."}, {"id": 24, "question": "A child who calls a zebra a &quot;horse&quot; later builds a new category after being corrected. Piaget would call this second process:", "options": ["Centration", "Assimilation", "Equilibrium", "Accommodation"], "correctAnswer": 3, "subject": "Development, Child & Adolescent", "subtopic": "", "difficulty": "", "explanation": "<p>Accommodation</p><p class=\"ex-why\"><b>Why:</b> Accommodation is changing an existing schema or creating a new one to fit new information. Forming a new ‘zebra’ category after correction is accommodation.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Centration — Centration is focusing on one feature and ignoring others.</li><li>(B) Assimilation — Calling the zebra a ‘horse’ at first was assimilation — fitting new information into an existing schema.</li><li>(C) Equilibrium — Equilibration is the balancing process that drives both, not this specific step.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Piaget’s four stages: sensorimotor, preoperational, concrete operational, formal operational.</li><li>Disequilibrium motivates the shift to accommodation.</li></ul>", "examWatch": "A fresh, predicted question. The neighbouring topics are asked often, so it is worth knowing."}, {"id": 25, "question": "The Cannon–Bard theory of emotion proposes that:", "options": ["The thalamus plays a central role in producing emotions", "The cerebellum must give the go ahead for emotions", "Activity in the occipital and parietal lobe happens simultaneously to produce emotions", "The sympathetic and parasympathetic nervous system works in concert"], "correctAnswer": 0, "subject": "Social, Positive & Indian Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>The thalamus plays a central role in producing emotions</p><p class=\"ex-why\"><b>Why:</b> Cannon–Bard theory (1927) says the thalamus sends signals at the same time to the cortex (felt emotion) and to the body (arousal), so the feeling and bodily change happen together, not one after the other.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) The cerebellum must give the go ahead for emotions — The cerebellum is not given this role.</li><li>(C) Activity in the occipital and parietal lobe happens simultaneously to produce emotions — The theory does not involve occipital and parietal lobes.</li><li>(D) The sympathetic and parasympathetic nervous system works in concert — It does not focus on the two autonomic branches working together.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>James–Lange: bodily change comes first, and the emotion is the perception of it.</li><li>Schachter–Singer two-factor theory: arousal plus a cognitive label.</li></ul>", "examWatch": "This is an actual previous-year question. Examiners do repeat questions, sometimes word for word — make sure you can answer it instantly."}, {"id": 26, "question": "Weber&#x27;s law, well established in perceptual research, states that:", "options": ["A stimulus must be increased by equal value to be just noticeably different", "A stimulus must be increased by twice its amount to be noticeably different", "A stimulus must be increased by a constant fraction of its value to be just noticeably different", "A stimulus must be increased by ten times as amount to be just noticeably different"], "correctAnswer": 2, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>A stimulus must be increased by a constant fraction of its value to be just noticeably different</p><p class=\"ex-why\"><b>Why:</b> Weber’s law states that the just noticeable difference (JND) is a constant fraction of the original stimulus: ΔI / I = k. A heavier weight needs a bigger change to be noticed.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) A stimulus must be increased by equal value to be just noticeably different — The change is not an equal absolute amount.</li><li>(B) A stimulus must be increased by twice its amount to be noticeably different — Doubling is not the rule.</li><li>(D) A stimulus must be increased by ten times as amount to be just noticeably different — Ten times is not the rule.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Fechner extended this into Fechner’s law: sensation grows with the logarithm of stimulus intensity.</li><li>Stevens’ power law is another psychophysical law.</li></ul>", "examWatch": "A real past-paper question. Repeats are common, so learn it exactly as it is."}, {"id": 27, "question": "The &#x27;Direct Perception&#x27; theory of perception is associated with:", "options": ["Endel Tulving", "Jerome Bruner", "J.J. Gibson", "Gregory Bateson"], "correctAnswer": 2, "subject": "Core Psychological Processes", "subtopic": "", "difficulty": "", "explanation": "<p>J.J. Gibson</p><p class=\"ex-why\"><b>Why:</b> J.J. Gibson’s ecological theory of direct perception holds that the environment contains enough information (e.g. texture gradients, affordances) to be perceived directly, without inference — a bottom-up view.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Endel Tulving — Tulving is known for episodic and semantic memory.</li><li>(B) Jerome Bruner — Bruner is known for top-down ‘New Look’ perception and discovery learning.</li><li>(D) Gregory Bateson — Bateson is known for the double-bind theory.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Affordances are what the environment offers for action.</li><li>Gregory’s constructivist view is the top-down alternative.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this exact question has come before. Make sure you never lose this mark."}, {"id": 28, "question": "Learning by observing the behaviour of others and noting its consequences is known as:", "options": ["Vicarious learning", "Vicious learning", "Ventral learning", "Vexed learning"], "correctAnswer": 0, "subject": "Core Psychological Processes", "subtopic": "", "difficulty": "", "explanation": "<p>Vicarious learning</p><p class=\"ex-why\"><b>Why:</b> Vicarious learning means learning by watching others and seeing the consequences of their actions — central to Bandura’s social learning theory.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Vicious learning — ‘Vicious learning’ is not a psychological term.</li><li>(C) Ventral learning — ‘Ventral learning’ is not a psychological term.</li><li>(D) Vexed learning — ‘Vexed learning’ is not a psychological term.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Bandura’s Bobo doll study (1961) showed observational learning of aggression.</li><li>Four steps of modelling: attention, retention, reproduction, motivation.</li></ul>", "examWatch": "This is an actual previous-year question. Examiners do repeat questions, sometimes word for word — make sure you can answer it instantly."}, {"id": 29, "question": "The theory of operant conditioning is associated with:", "options": ["Pavlov", "Watson", "Skinner", "Bandura"], "correctAnswer": 2, "subject": "Core Psychological Processes", "subtopic": "", "difficulty": "", "explanation": "<p>Skinner</p><p class=\"ex-why\"><b>Why:</b> B.F. Skinner developed operant conditioning: behaviour is shaped by its consequences (reinforcement and punishment), studied with the Skinner box.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Pavlov — Pavlov developed classical conditioning.</li><li>(B) Watson — Watson founded behaviourism and the ‘Little Albert’ study.</li><li>(D) Bandura — Bandura developed social learning theory.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Thorndike’s law of effect came before Skinner’s operant work.</li><li>Schedules of reinforcement: fixed and variable ratio and interval.</li></ul>", "examWatch": "A real past-paper question. Repeats are common, so learn it exactly as it is."}, {"id": 30, "question": "According to the Yerkes–Dodson law, compared with an easy task, the optimal level of arousal for a difficult task is:", "options": ["Higher", "The same", "Irrelevant to performance", "Lower"], "correctAnswer": 3, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Lower</p><p class=\"ex-why\"><b>Why:</b> The Yerkes–Dodson law (1908) describes an inverted-U link between arousal and performance. For difficult tasks the best level of arousal is lower than for easy tasks.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Higher — Higher arousal helps easy tasks, not difficult ones.</li><li>(B) The same — The best level changes with task difficulty.</li><li>(C) Irrelevant to performance — Arousal clearly affects performance.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Too little arousal causes boredom; too much causes anxiety and errors.</li><li>Hull’s drive theory predicted a simpler, straight-line link.</li></ul>", "examWatch": "This angle is new, but the topic around it is popular with examiners — don’t skip it."}, {"id": 31, "question": "Case: Mr V got an A+ in his mathematics test but immediately concluded that the paper must have been too easy, otherwise he would not have scored so well. He habitually dismisses his own good experiences. Which cognitive distortion is he showing?", "options": ["Catastrophizing", "Disqualifying the positive", "All-or-nothing thinking", "Shaping"], "correctAnswer": 1, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Disqualifying the positive</p><p class=\"ex-why\"><b>Why:</b> Disqualifying the positive means rejecting good experiences by insisting they ‘don’t count’ — here, deciding the paper was too easy.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Catastrophizing — Catastrophising is expecting the worst outcome.</li><li>(C) All-or-nothing thinking — All-or-nothing thinking sees things in only two categories.</li><li>(D) Shaping — Shaping is a behavioural technique, not a cognitive distortion.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Cognitive distortions were described by Beck and popularised by David Burns.</li><li>Others: mind reading, overgeneralisation, mental filter, personalisation.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this exact question has come before. Make sure you never lose this mark."}, {"id": 32, "question": "According to the preconventional level of morality in Kohlberg&#x27;s theory:", "options": ["Right and wrong are defined by the hedonistic consequences of a given action", "It is based on social rules", "Moral rules are seen as convention, designed to ensure greater good", "None of the above"], "correctAnswer": 0, "subject": "Development, Child & Adolescent", "subtopic": "", "difficulty": "", "explanation": "<p>Right and wrong are defined by the hedonistic consequences of a given action</p><p class=\"ex-why\"><b>Why:</b> At Kohlberg’s preconventional level (stages 1 and 2), right and wrong are judged by the personal consequences of an action — avoiding punishment or getting rewards.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) It is based on social rules — Following social rules is the conventional level.</li><li>(C) Moral rules are seen as convention, designed to ensure greater good — Seeing rules as social contracts for the greater good is the postconventional level.</li><li>(D) None of the above — Option A is correct, so ‘none of the above’ is wrong.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Stage 1: obedience and punishment; Stage 2: individualism and exchange.</li><li>Carol Gilligan criticised Kohlberg for male bias.</li></ul>", "examWatch": "This is an actual previous-year question. Examiners do repeat questions, sometimes word for word — make sure you can answer it instantly."}, {"id": 33, "question": "The &quot;disorganised&quot; attachment category was added to the strange-situation classification by:", "options": ["Ainsworth", "Bowlby", "Harlow", "Main and Solomon"], "correctAnswer": 3, "subject": "Development, Child & Adolescent", "subtopic": "", "difficulty": "", "explanation": "<p>Main and Solomon</p><p class=\"ex-why\"><b>Why:</b> Mary Main and Judith Solomon (1986/1990) added the ‘disorganised/disoriented’ category to Ainsworth’s secure, avoidant and resistant types.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Ainsworth — Ainsworth described the first three patterns.</li><li>(B) Bowlby — Bowlby proposed attachment theory but not this category.</li><li>(C) Harlow — Harlow studied contact comfort in monkeys.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Disorganised attachment is linked with frightening or abusive caregiving.</li><li>Main also developed the Adult Attachment Interview.</li></ul>", "examWatch": "Not asked directly yet, but it sits right next to frequently asked topics — it may appear in a new form."}, {"id": 34, "question": "According to Bandura, the most powerful source of self-efficacy is:", "options": ["Vicarious experiences", "Physiological arousal", "Mastery experiences", "Verbal persuasion"], "correctAnswer": 2, "subject": "Social, Positive & Indian Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Mastery experiences</p><p class=\"ex-why\"><b>Why:</b> Bandura said mastery (enactive) experiences — succeeding yourself — are the strongest source of self-efficacy.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Vicarious experiences — Vicarious experience (watching others succeed) is weaker.</li><li>(B) Physiological arousal — Physiological states are the weakest source.</li><li>(D) Verbal persuasion — Verbal persuasion is a weaker source.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The four sources: mastery, vicarious experience, verbal persuasion, physiological and emotional states.</li><li>Self-efficacy differs from self-esteem — it is task-specific.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a likely new area. Learn the key points above."}, {"id": 35, "question": "<div class=\"ar-block\"><div class=\"ar-row\"><span class=\"ar-label\">Assertion (A)</span><span class=\"ar-text\">With normal ageing, fluid intelligence declines while crystallized intelligence remains relatively stable.</span></div><div class=\"ar-row\"><span class=\"ar-label\">Reason (R)</span><span class=\"ar-text\">Crystallized intelligence rests on accumulated knowledge and experience, whereas fluid intelligence depends on the efficiency of the nervous system in novel problem solving.</span></div></div>", "options": ["Both A and R are true and R is the correct explanation of A.", "Both A and R are true but R is not the correct explanation of A.", "A is true but R is false.", "A is false but R is true."], "correctAnswer": 0, "subject": "Core Psychological Processes", "subtopic": "", "difficulty": "", "explanation": "<p>Both A and R are true and R is the correct explanation of A.</p><p class=\"ex-why\"><b>Why:</b> Both are true, and R explains A. Fluid intelligence depends on the speed and efficiency of the nervous system, which declines with age; crystallised intelligence depends on stored knowledge, which keeps growing or stays stable.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Both A and R are true but R is not the correct explanation of A. — B is wrong because R does explain A.</li><li>(C) A is true but R is false. — C is wrong because R is true.</li><li>(D) A is false but R is true. — D is wrong because A is true.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Gf–Gc theory was proposed by Cattell and developed with Horn.</li><li>Baltes’s SOC model explains successful ageing.</li></ul>", "examWatch": "Asked in earlier papers; examiners like to test it through a case or a NOT question."}, {"id": 36, "question": "Match Erikson&#x27;s psychosocial stage (List I) with its resolution virtue (List II): List I: (i) Trust vs Mistrust   (ii) Industry vs Inferiority   (iii) Identity vs Role Confusion   (iv) Generativity vs Stagnation List II: (P) Fidelity   (Q) Care   (R) Competence   (S) Hope", "options": ["i-S, ii-R, iii-P, iv-Q", "i-R, ii-S, iii-P, iv-Q", "i-S, ii-R, iii-Q, iv-P", "i-P, ii-R, iii-S, iv-Q"], "correctAnswer": 0, "subject": "Development, Child & Adolescent", "subtopic": "", "difficulty": "", "explanation": "<p>i-S, ii-R, iii-P, iv-Q</p><p class=\"ex-why\"><b>Why:</b> Erikson’s virtues: Trust vs Mistrust – Hope; Industry vs Inferiority – Competence; Identity vs Role Confusion – Fidelity; Generativity vs Stagnation – Care.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) i-R, ii-S, iii-P, iv-Q — Option B swaps trust and industry.</li><li>(C) i-S, ii-R, iii-Q, iv-P — Option C swaps identity and generativity.</li><li>(D) i-P, ii-R, iii-S, iv-Q — Option D swaps trust and identity.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Other virtues: autonomy – will; initiative – purpose; intimacy – love; integrity – wisdom.</li><li>Erikson described eight psychosocial stages.</li></ul>", "examWatch": "Questions on this have come before — a quick revision here pays off."}, {"id": 37, "question": "Arrange the stages of dying proposed by Elisabeth Kübler-Ross in the correct sequence:", "options": ["Anger, sadness, bargaining, denial, acceptance", "Denial, anger, bargaining, sadness, acceptance", "Bargaining, anger, denial, sadness, acceptance", "Acceptance, anger, bargaining, denial, sadness"], "correctAnswer": 1, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Denial, anger, bargaining, sadness, acceptance</p><p class=\"ex-why\"><b>Why:</b> Elisabeth Kübler-Ross (On Death and Dying, 1969): denial → anger → bargaining → depression (sadness) → acceptance.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Anger, sadness, bargaining, denial, acceptance — Denial comes first, not anger.</li><li>(C) Bargaining, anger, denial, sadness, acceptance — Bargaining comes after anger.</li><li>(D) Acceptance, anger, bargaining, denial, sadness — Acceptance is the last stage.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The stages are not strictly sequential; people move back and forth.</li><li>The model was based on interviews with dying patients.</li></ul>", "examWatch": "A real past-paper question. Repeats are common, so learn it exactly as it is."}, {"id": 38, "question": "Arrange the prominent personalities in clinical psychology in ascending (chronological) order:", "options": ["St. Augustine – Plato – Johann Weyer – William Harvey", "Plato – St. Augustine – William Harvey – Johann Weyer", "Plato – St. Augustine – Johann Weyer – William Harvey", "Plato – Johann Weyer – St. Augustine – William Harvey"], "correctAnswer": 2, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Plato – St. Augustine – Johann Weyer – William Harvey</p><p class=\"ex-why\"><b>Why:</b> Plato (about 400 BC) → St. Augustine (about 400 AD) → Johann Weyer (1500s, wrote against witch-hunts) → William Harvey (described blood circulation in 1628).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) St. Augustine – Plato – Johann Weyer – William Harvey — Augustine lived long after Plato.</li><li>(B) Plato – St. Augustine – William Harvey – Johann Weyer — Weyer’s work came before Harvey’s.</li><li>(D) Plato – Johann Weyer – St. Augustine – William Harvey — Augustine came long before Weyer.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Weyer is called the ‘father of modern psychiatry’ by some.</li><li>Hippocrates proposed the four humours.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this exact question has come before. Make sure you never lose this mark."}, {"id": 39, "question": "Jung&#x27;s archetype of the &quot;animus&quot; refers to:", "options": ["The masculine side of a female psyche", "The repressed animalistic part of the mind", "The feminine side of a male psyche", "The repressed unpleasant thoughts and memories"], "correctAnswer": 0, "subject": "Therapies & Interventions", "subtopic": "", "difficulty": "", "explanation": "<p>The masculine side of a female psyche</p><p class=\"ex-why\"><b>Why:</b> Jung’s animus is the unconscious masculine side in a woman’s psyche; the anima is the feminine side in a man’s psyche.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) The repressed animalistic part of the mind — The ‘animalistic part’ is a misunderstanding; Jung’s shadow is the dark, repressed side.</li><li>(C) The feminine side of a male psyche — The feminine side of a male psyche is the anima.</li><li>(D) The repressed unpleasant thoughts and memories — Repressed unpleasant memories belong to the personal unconscious.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Other archetypes: persona, shadow, self.</li><li>Jung described the collective unconscious.</li></ul>", "examWatch": "This is an actual previous-year question. Examiners do repeat questions, sometimes word for word — make sure you can answer it instantly."}, {"id": 40, "question": "The classification of infant temperament into difficult, easy and slow-to-warm-up was proposed by:", "options": ["Alfred Adler", "Carl Jung", "Thomas & Chess", "James Lange"], "correctAnswer": 2, "subject": "Development, Child & Adolescent", "subtopic": "", "difficulty": "", "explanation": "<p>Thomas &amp; Chess</p><p class=\"ex-why\"><b>Why:</b> Alexander Thomas and Stella Chess (New York Longitudinal Study, 1956 onwards) described easy, difficult and slow-to-warm-up temperaments.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Alfred Adler — Adler proposed individual psychology and the inferiority complex.</li><li>(B) Carl Jung — Jung proposed analytical psychology.</li><li>(D) James Lange — James and Lange proposed a theory of emotion.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>About 40% easy, 10% difficult, 15% slow-to-warm-up; the rest did not fit a category.</li><li>Goodness of fit: match between temperament and environment.</li></ul>", "examWatch": "A real past-paper question. Repeats are common, so learn it exactly as it is."}, {"id": 41, "question": "The ERG theory of motivation (Existence, Relatedness, Growth) was proposed by:", "options": ["Alderfer", "Maslow", "Herzberg", "McClelland"], "correctAnswer": 0, "subject": "Social, Positive & Indian Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Alderfer</p><p class=\"ex-why\"><b>Why:</b> Clayton Alderfer (1969) condensed Maslow’s hierarchy into Existence, Relatedness and Growth needs. More than one need can act at once, and frustration can cause regression.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Maslow — Maslow proposed the five-level hierarchy.</li><li>(C) Herzberg — Herzberg proposed the two-factor (motivator–hygiene) theory.</li><li>(D) McClelland — McClelland proposed needs for achievement, affiliation and power.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>ERG’s ‘frustration–regression’ principle is a key difference from Maslow.</li><li>Vroom proposed expectancy theory.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this exact question has come before. Make sure you never lose this mark."}, {"id": 42, "question": "Match the concept (List I) with the theorist (List II): List I: (i) Borderline personality organization   (ii) Cohesive self (self psychology)   (iii) Transitional object   (iv) Paranoid-schizoid position List II: (P) Melanie Klein   (Q) Heinz Kohut   (R) Donald Winnicott   (S) Otto Kernberg", "options": ["i-Q, ii-S, iii-R, iv-P", "i-S, ii-Q, iii-P, iv-R", "i-S, ii-Q, iii-R, iv-P", "i-P, ii-R, iii-Q, iv-S"], "correctAnswer": 2, "subject": "Psychopathology, Classification & Law", "subtopic": "", "difficulty": "", "explanation": "<p>i-S, ii-Q, iii-R, iv-P</p><p class=\"ex-why\"><b>Why:</b> Kernberg – borderline personality organisation; Kohut – cohesive self (self psychology); Winnicott – transitional object; Klein – paranoid-schizoid position.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) i-Q, ii-S, iii-R, iv-P — Option A swaps Kernberg and Kohut.</li><li>(B) i-S, ii-Q, iii-P, iv-R — Option B swaps Winnicott and Klein.</li><li>(D) i-P, ii-R, iii-Q, iv-S — Option D mismatches every pair.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Winnicott also described the ‘good-enough mother’.</li><li>Klein’s two positions: paranoid-schizoid and depressive.</li></ul>", "examWatch": "Seen in past papers more than once. Know the difference between the options well."}, {"id": 43, "question": "The concept of &#x27;psychopathic inferiority&#x27; was introduced by:", "options": ["Julius Koch", "Karl Schneider", "Leon Festinger", "James Lange"], "correctAnswer": 0, "subject": "Psychopathology, Classification & Law", "subtopic": "", "difficulty": "", "explanation": "<p>Julius Koch</p><p class=\"ex-why\"><b>Why:</b> J.L.A. Koch introduced ‘psychopathic inferiority’ in 1891, an early term for what later became psychopathic or antisocial personality.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Karl Schneider — Kurt Schneider later classified psychopathic personalities (1923), but he did not coin this term.</li><li>(C) Leon Festinger — Festinger proposed cognitive dissonance.</li><li>(D) James Lange — Lange proposed a theory of emotion with James.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Prichard (1835) described ‘moral insanity’.</li><li>Cleckley’s The Mask of Sanity (1941) described psychopathy.</li></ul>", "examWatch": "This is an actual previous-year question. Examiners do repeat questions, sometimes word for word — make sure you can answer it instantly."}, {"id": 44, "question": "All of the following are mature defence mechanisms EXCEPT:", "options": ["Humor", "Altruism", "Suppression", "Projection"], "correctAnswer": 3, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Projection</p><p class=\"ex-why\"><b>Why:</b> Projection is an immature defence. Humour, altruism and suppression are mature defences in Vaillant’s hierarchy.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Humor — Humour is mature.</li><li>(B) Altruism — Altruism is mature.</li><li>(C) Suppression — Suppression (consciously putting a worry aside) is mature.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Other mature defences: sublimation and anticipation.</li><li>Vaillant’s levels: psychotic, immature, neurotic, mature.</li></ul>", "examWatch": "A real past-paper question. Repeats are common, so learn it exactly as it is."}, {"id": 45, "question": "A man with intense aggressive urges becomes a professional boxer. The defence mechanism chiefly involved is:", "options": ["Sublimation", "Projection", "Undoing", "Reaction formation"], "correctAnswer": 0, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Sublimation</p><p class=\"ex-why\"><b>Why:</b> Sublimation channels unacceptable impulses into socially acceptable activities — here, aggression into professional boxing.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Projection — Projection attributes one’s own impulses to others.</li><li>(C) Undoing — Undoing is acting to ‘cancel out’ an unacceptable thought or act.</li><li>(D) Reaction formation — Reaction formation is acting in the opposite way to the impulse.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Freud saw sublimation as the healthiest defence.</li><li>Anna Freud described defence mechanisms in detail (1936).</li></ul>", "examWatch": "A fresh, predicted question. The neighbouring topics are asked often, so it is worth knowing."}, {"id": 46, "question": "Which of these is NOT considered a cardinal feature of Borderline Personality Disorder (BPD)?", "options": ["'Eccentric' behaviour marked by odd patterns of thinking and communication", "An enduring pattern of instability in personal relationships", "A lack of a well-defined and stable self-image", "Regular and unpredictable changes in mood"], "correctAnswer": 0, "subject": "Psychopathology, Classification & Law", "subtopic": "", "difficulty": "", "explanation": "<p>&#x27;Eccentric&#x27; behaviour marked by odd patterns of thinking and communication</p><p class=\"ex-why\"><b>Why:</b> Odd, eccentric thinking and communication belong to schizotypal personality disorder (Cluster A), not borderline personality disorder.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) An enduring pattern of instability in personal relationships — Unstable relationships are a core BPD feature.</li><li>(C) A lack of a well-defined and stable self-image — Identity disturbance is a core BPD feature.</li><li>(D) Regular and unpredictable changes in mood — Rapid mood changes (affective instability) are a core BPD feature.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Other BPD features: fear of abandonment, impulsivity, self-harm, chronic emptiness, intense anger.</li><li>DBT (Linehan) is the best-known treatment.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this exact question has come before. Make sure you never lose this mark."}, {"id": 47, "question": "Which pair completes the statement? &quot;______ theory maximized and ______ theory minimized the role of the unconscious.&quot;", "options": ["Trait; Humanistic", "Psychoanalytic; Behaviourist", "Psychoanalytic; Humanistic", "Trait; Behaviourist"], "correctAnswer": 1, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Psychoanalytic; Behaviourist</p><p class=\"ex-why\"><b>Why:</b> Psychoanalytic theory places the unconscious at the centre; behaviourism largely ignores it, studying only observable behaviour.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Trait; Humanistic — Trait theory does not maximise the unconscious.</li><li>(C) Psychoanalytic; Humanistic — Humanistic theory focuses on conscious experience, but behaviourism is the clearer ‘minimiser’ in this pair.</li><li>(D) Trait; Behaviourist — Trait theory does not maximise the unconscious.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Freud’s topographic model: conscious, preconscious, unconscious.</li><li>Watson’s 1913 ‘behaviourist manifesto’ rejected study of the mind.</li></ul>", "examWatch": "This is an actual previous-year question. Examiners do repeat questions, sometimes word for word — make sure you can answer it instantly."}, {"id": 48, "question": "Which personality disorder is characterized by marked impulsive, hostile, manipulative behaviours without any guilt or remorse (ICD-10)?", "options": ["Histrionic personality", "Narcissistic personality", "Borderline personality", "Dissocial personality"], "correctAnswer": 3, "subject": "Psychopathology, Classification & Law", "subtopic": "", "difficulty": "", "explanation": "<p>Dissocial personality</p><p class=\"ex-why\"><b>Why:</b> ICD-10 dissocial personality disorder (F60.2) shows callous disregard for others, irresponsibility, low frustration tolerance, aggression and lack of guilt.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Histrionic personality — Histrionic personality shows attention-seeking and shallow emotion.</li><li>(B) Narcissistic personality — Narcissistic personality shows grandiosity and need for admiration.</li><li>(C) Borderline personality — Borderline (emotionally unstable) personality shows unstable mood and relationships.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>DSM-5 calls it antisocial personality disorder; conduct disorder before age 15 is needed.</li><li>Cleckley and Hare described psychopathy.</li></ul>", "examWatch": "A real past-paper question. Repeats are common, so learn it exactly as it is."}, {"id": 49, "question": "Which of these is NOT part of the Cluster B personality disorders?", "options": ["Narcissistic personality disorder", "Obsessive-compulsive personality disorder", "Histrionic personality disorder", "Borderline personality disorder"], "correctAnswer": 1, "subject": "Psychopathology, Classification & Law", "subtopic": "", "difficulty": "", "explanation": "<p>Obsessive-compulsive personality disorder</p><p class=\"ex-why\"><b>Why:</b> Obsessive-compulsive personality disorder is in Cluster C (anxious-fearful), with avoidant and dependent personality disorders.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Narcissistic personality disorder — Narcissistic PD is in Cluster B.</li><li>(C) Histrionic personality disorder — Histrionic PD is in Cluster B.</li><li>(D) Borderline personality disorder — Borderline PD is in Cluster B.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Cluster B also includes antisocial PD (dramatic-erratic).</li><li>Cluster A: paranoid, schizoid, schizotypal.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this exact question has come before. Make sure you never lose this mark."}, {"id": 50, "question": "The &quot;Barnum effect&quot; refers to:", "options": ["The tendency of people to accept and approve of the interpretation of their personalities that you give them", "The tendency of people to not accept and disapprove of the interpretation of their personalities that you give them", "The tendency of people to remain neutral of the interpretation of their personalities that you give them", "The tendency of people to seek more information before they accept or disapprove of the interpretation of their personalities that you give them"], "correctAnswer": 0, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>The tendency of people to accept and approve of the interpretation of their personalities that you give them</p><p class=\"ex-why\"><b>Why:</b> The Barnum (Forer) effect is the tendency to accept vague, general personality descriptions as accurate for oneself.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) The tendency of people to not accept and disapprove of the interpretation of their personalities that you give them — People tend to accept, not reject, such descriptions.</li><li>(C) The tendency of people to remain neutral of the interpretation of their personalities that you give them — People do not stay neutral; they tend to agree.</li><li>(D) The tendency of people to seek more information before they accept or disapprove of the interpretation of their personalities that you give them — People usually accept such statements without seeking more information.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Bertram Forer demonstrated it in 1949; Meehl named it after P.T. Barnum.</li><li>It explains belief in horoscopes and some ‘personality readings’.</li></ul>", "examWatch": "This is an actual previous-year question. Examiners do repeat questions, sometimes word for word — make sure you can answer it instantly."}, {"id": 51, "question": "Which formula is used to compute the ratio IQ?", "options": ["MA/CA × 100", "CA/MA × 100", "CA/MA − 100", "MA/CA + 100"], "correctAnswer": 0, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>MA/CA × 100</p><p class=\"ex-why\"><b>Why:</b> Ratio IQ = Mental Age ÷ Chronological Age × 100 (William Stern’s idea, used by Terman in the 1916 Stanford–Binet).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) CA/MA × 100 — The ages are reversed.</li><li>(C) CA/MA − 100 — Ages are divided and then multiplied by 100, not subtracted.</li><li>(D) MA/CA + 100 — 100 is not added.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Modern tests use deviation IQ (mean 100, SD 15).</li><li>Ratio IQ fails for adults, as mental age stops rising.</li></ul>", "examWatch": "A real past-paper question. Repeats are common, so learn it exactly as it is."}, {"id": 52, "question": "The Millon Clinical Multiaxial Inventory (MCMI-III) consists of how many items?", "options": ["175", "250", "108", "567"], "correctAnswer": 0, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>175</p><p class=\"ex-why\"><b>Why:</b> The MCMI-III (Millon) has 175 true/false items and is aligned with DSM personality disorders.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) 250 — 250 is not its item count.</li><li>(C) 108 — 108 is not its item count.</li><li>(D) 567 — 567 items is the MMPI-2.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The MCMI-IV (2015) has 195 items.</li><li>MMPI-2-RF has 338 items; MMPI-A has 478.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this exact question has come before. Make sure you never lose this mark."}, {"id": 53, "question": "Which of the following statements is correct? (Asked in JEMAS(PG) 2023, M.Phil CP)", "options": ["The MMPI has 15 clinical scales apart from the validity scales.", "The MMPI has 10 clinical scales apart from the validity scales.", "Scale 7 (Psychasthenia) of the MMPI-2 measures masculine and feminine interests.", "Scale 7 (Psychasthenia) of the MMPI-2 measures antisocial behaviour."], "correctAnswer": 1, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>The MMPI has 10 clinical scales apart from the validity scales.</p><p class=\"ex-why\"><b>Why:</b> The MMPI/MMPI-2 has 10 clinical scales besides the validity scales (L, F, K and others).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) The MMPI has 15 clinical scales apart from the validity scales. — 15 is not the number of clinical scales.</li><li>(C) Scale 7 (Psychasthenia) of the MMPI-2 measures masculine and feminine interests. — Masculinity–femininity is Scale 5.</li><li>(D) Scale 7 (Psychasthenia) of the MMPI-2 measures antisocial behaviour. — Antisocial behaviour is mainly measured by Scale 4 (Psychopathic deviate); Scale 7 measures anxiety and obsessive symptoms.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>MMPI was developed by Hathaway and McKinley (1943) using empirical keying.</li><li>Scale 2 = depression; Scale 8 = schizophrenia; Scale 0 = social introversion.</li></ul>", "examWatch": "This is an actual previous-year question. Examiners do repeat questions, sometimes word for word — make sure you can answer it instantly."}, {"id": 54, "question": "Case: A 38-year-old woman leaves home after a family quarrel. Twelve days later she is found in a village about 500 km away, working as a field labourer. She cannot recall who she is. The most likely diagnosis is:", "options": ["Dissociative amnesia", "Dissociative fugue", "Dissociative identity disorder", "Factitious disorder"], "correctAnswer": 1, "subject": "Core Psychological Processes", "subtopic": "", "difficulty": "", "explanation": "<p>Dissociative fugue</p><p class=\"ex-why\"><b>Why:</b> Sudden, unplanned travel away from home with loss of personal identity is dissociative fugue. DSM-5 now treats it as a specifier of dissociative amnesia (‘with dissociative fugue’).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Dissociative amnesia — Dissociative amnesia alone does not involve purposeful travel and a new life.</li><li>(C) Dissociative identity disorder — DID involves two or more distinct identities.</li><li>(D) Factitious disorder — Factitious disorder is faking illness to take on the sick role.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Fugue often follows severe stress.</li><li>RINPAS 2024 asked a very similar case.</li></ul>", "examWatch": "A real past-paper question. Repeats are common, so learn it exactly as it is."}, {"id": 55, "question": "Case: A soldier witnessed brutal killings and the screams of children during a war. After returning home he has recurring haunting memories and nightmares, numbed social withdrawal, jumpy anxiety and insomnia. He may be experiencing:", "options": ["Post-Traumatic Stress disorder", "Generalised Anxiety Disorder", "Dissociative Disorder", "None of the Above"], "correctAnswer": 0, "subject": "Development, Child & Adolescent", "subtopic": "", "difficulty": "", "explanation": "<p>Post-Traumatic Stress disorder</p><p class=\"ex-why\"><b>Why:</b> Intrusive memories, nightmares, numbing, avoidance, jumpiness and insomnia after a life-threatening trauma make up PTSD.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Generalised Anxiety Disorder — GAD is excessive worry about many everyday matters, not tied to trauma.</li><li>(C) Dissociative Disorder — Dissociative disorders involve disruption of identity, memory or awareness.</li><li>(D) None of the Above — PTSD clearly fits, so ‘none’ is wrong.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>DSM-5 PTSD has four clusters: intrusion, avoidance, negative changes in mood and cognition, arousal.</li><li>Symptoms must last more than 1 month.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this exact question has come before. Make sure you never lose this mark."}, {"id": 56, "question": "Case: Rajat has sudden, unpredictable episodes of intense dread with shortness of breath and heart palpitations, which come and go. He is most likely suffering from:", "options": ["Generalised anxiety disorder", "Obsessive Compulsive Disorder", "Panic Disorder", "Post-Traumatic Stress Disorder"], "correctAnswer": 2, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Panic Disorder</p><p class=\"ex-why\"><b>Why:</b> Recurrent, unexpected panic attacks with intense fear, breathlessness and palpitations point to panic disorder.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Generalised anxiety disorder — GAD is ongoing worry, not sudden attacks.</li><li>(B) Obsessive Compulsive Disorder — OCD involves obsessions and compulsions.</li><li>(D) Post-Traumatic Stress Disorder — PTSD follows a traumatic event.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Diagnosis also needs 1 month of worry about attacks or a change in behaviour.</li><li>Clark’s cognitive model: catastrophic misinterpretation of bodily sensations.</li></ul>", "examWatch": "This is an actual previous-year question. Examiners do repeat questions, sometimes word for word — make sure you can answer it instantly."}, {"id": 57, "question": "Match the syndrome (List I) with its feature (List II): List I: (i) Othello syndrome   (ii) Ganser&#x27;s syndrome   (iii) Munchausen&#x27;s syndrome   (iv) Klüver–Bucy syndrome List II: (P) Approximate answers   (Q) Delusion of infidelity of the partner   (R) Fabricating illness to obtain medical attention   (S) Hypersexuality, visual agnosia and compulsive oral exploration", "options": ["i-P, ii-Q, iii-R, iv-S", "i-Q, ii-P, iii-S, iv-R", "i-Q, ii-P, iii-R, iv-S", "i-Q, ii-R, iii-P, iv-S"], "correctAnswer": 2, "subject": "Biological Psychology & Neuropsychology", "subtopic": "", "difficulty": "", "explanation": "<p>i-Q, ii-P, iii-R, iv-S</p><p class=\"ex-why\"><b>Why:</b> Othello syndrome – delusion of a partner’s infidelity; Ganser syndrome – approximate answers; Munchausen syndrome – fabricating illness for medical attention; Klüver–Bucy syndrome – hypersexuality, visual agnosia and oral exploration.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) i-P, ii-Q, iii-R, iv-S — Option A swaps Othello and Ganser.</li><li>(B) i-Q, ii-P, iii-S, iv-R — Option B swaps Munchausen and Klüver–Bucy.</li><li>(D) i-Q, ii-R, iii-P, iv-S — Option D swaps Ganser and Munchausen.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Ganser syndrome was first described in prisoners.</li><li>Munchausen by proxy is now called factitious disorder imposed on another.</li></ul>", "examWatch": "This area has appeared in previous papers. It may well come in your exam too."}, {"id": 58, "question": "Schneider&#x27;s &quot;First Rank Symptoms&quot; of schizophrenia include all of the following EXCEPT:", "options": ["Depersonalisation", "Running commentary of one's thoughts", "Primary delusion", "Somatic passivity"], "correctAnswer": 0, "subject": "Psychopathology, Classification & Law", "subtopic": "", "difficulty": "", "explanation": "<p>Depersonalisation</p><p class=\"ex-why\"><b>Why:</b> Depersonalisation is not one of Schneider’s first-rank symptoms. FRS include audible thoughts, running commentary voices, voices arguing, thought insertion, withdrawal and broadcasting, passivity experiences and delusional perception.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Running commentary of one&#x27;s thoughts — Running commentary is a first-rank symptom.</li><li>(C) Primary delusion — Primary delusion (delusional perception) is a first-rank symptom.</li><li>(D) Somatic passivity — Somatic passivity is a first-rank symptom.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Kurt Schneider published FRS in 1959.</li><li>FRS are not specific to schizophrenia; DSM-5 removed their special weight.</li></ul>", "examWatch": "A real past-paper question. Repeats are common, so learn it exactly as it is."}, {"id": 59, "question": "Which of the following is NOT a part of Gerstmann syndrome?", "options": ["Prosopagnosia", "Left-right disorientation", "Agraphia", "Dyscalculia"], "correctAnswer": 0, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Prosopagnosia</p><p class=\"ex-why\"><b>Why:</b> Gerstmann syndrome (dominant angular gyrus) has four features: finger agnosia, agraphia, acalculia and left–right disorientation. Prosopagnosia is not part of it.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Left-right disorientation — Left–right disorientation is a core feature.</li><li>(C) Agraphia — Agraphia is a core feature.</li><li>(D) Dyscalculia — Dyscalculia (acalculia) is a core feature.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Josef Gerstmann described it in 1924.</li><li>Prosopagnosia follows fusiform gyrus damage.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this exact question has come before. Make sure you never lose this mark."}, {"id": 60, "question": "Which triad characterises dementia with Lewy bodies?", "options": ["Aphasia, apraxia, agnosia", "Chorea, depression, dementia", "Visual hallucinations, fluctuating cognition, parkinsonism", "Gait disturbance, urinary incontinence, dementia"], "correctAnswer": 2, "subject": "Biological Psychology & Neuropsychology", "subtopic": "", "difficulty": "", "explanation": "<p>Visual hallucinations, fluctuating cognition, parkinsonism</p><p class=\"ex-why\"><b>Why:</b> Dementia with Lewy bodies has three core features: recurrent visual hallucinations, fluctuating cognition and parkinsonism (plus REM sleep behaviour disorder).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Aphasia, apraxia, agnosia — Aphasia, apraxia and agnosia are typical of Alzheimer’s disease.</li><li>(B) Chorea, depression, dementia — Chorea, depression and dementia point to Huntington’s disease.</li><li>(D) Gait disturbance, urinary incontinence, dementia — Gait problems, incontinence and dementia are normal pressure hydrocephalus.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Severe sensitivity to antipsychotics is a key warning sign.</li><li>Lewy bodies are made of alpha-synuclein.</li></ul>", "examWatch": "This angle is new, but the topic around it is popular with examiners — don’t skip it."}, {"id": 61, "question": "According to DSM-5, signs of the disturbance in schizophrenia must persist continuously for at least:", "options": ["12 months", "6 months", "3 months", "1 month"], "correctAnswer": 1, "subject": "Psychopathology, Classification & Law", "subtopic": "", "difficulty": "", "explanation": "<p>6 months</p><p class=\"ex-why\"><b>Why:</b> DSM-5 schizophrenia needs continuous signs for at least 6 months, including at least 1 month of active-phase symptoms.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) 12 months — 12 months is not required.</li><li>(C) 3 months — Under 6 months is schizophreniform disorder.</li><li>(D) 1 month — 1 month is the active-phase minimum, not the total duration.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Brief psychotic disorder: 1 day to under 1 month.</li><li>Schizophreniform: 1 to under 6 months.</li></ul>", "examWatch": "Not asked directly yet, but it sits right next to frequently asked topics — it may appear in a new form."}, {"id": 62, "question": "In adults, the minimum duration required for a diagnosis of persistent depressive disorder (dysthymia) in DSM-5 is:", "options": ["6 months", "1 year", "2 years", "5 years"], "correctAnswer": 2, "subject": "Psychopathology, Classification & Law", "subtopic": "", "difficulty": "", "explanation": "<p>2 years</p><p class=\"ex-why\"><b>Why:</b> Persistent depressive disorder (dysthymia) needs depressed mood most days for at least 2 years in adults (1 year in children and adolescents).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) 6 months — 6 months is too short.</li><li>(B) 1 year — 1 year applies to children and adolescents.</li><li>(D) 5 years — 5 years is not required.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>DSM-5 merged chronic major depression and dysthymia into PDD.</li><li>‘Double depression’ is MDD on top of dysthymia.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a likely new area. Learn the key points above."}, {"id": 63, "question": "Which antipsychotic requires mandatory haematological monitoring because of the risk of agranulocytosis?", "options": ["Haloperidol", "Olanzapine", "Clozapine", "Risperidone"], "correctAnswer": 2, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Clozapine</p><p class=\"ex-why\"><b>Why:</b> Clozapine can cause agranulocytosis (dangerous drop in white cells), so regular blood counts are compulsory. It is the drug of choice for treatment-resistant schizophrenia.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Haloperidol — Haloperidol’s main risks are extrapyramidal side effects.</li><li>(B) Olanzapine — Olanzapine’s main risks are weight gain and metabolic problems.</li><li>(D) Risperidone — Risperidone’s main risks include raised prolactin.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Clozapine also lowers suicide risk in schizophrenia.</li><li>Other clozapine effects: seizures, myocarditis, hypersalivation.</li></ul>", "examWatch": "A fresh, predicted question. The neighbouring topics are asked often, so it is worth knowing."}, {"id": 64, "question": "Lithium, a drug with a narrow therapeutic index, is a first-line mood stabiliser in:", "options": ["Bipolar disorder", "Schizophrenia", "Obsessive-compulsive disorder", "Panic disorder"], "correctAnswer": 0, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Bipolar disorder</p><p class=\"ex-why\"><b>Why:</b> Lithium is a first-line mood stabiliser for bipolar disorder, for both mania and maintenance. Its narrow therapeutic range needs serum level monitoring.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Schizophrenia — Schizophrenia is mainly treated with antipsychotics.</li><li>(C) Obsessive-compulsive disorder — OCD is mainly treated with SSRIs and ERP.</li><li>(D) Panic disorder — Panic disorder is mainly treated with SSRIs and CBT.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Lithium toxicity: tremor, vomiting, confusion, ataxia.</li><li>John Cade introduced lithium in 1949.</li></ul>", "examWatch": "This angle is new, but the topic around it is popular with examiners — don’t skip it."}, {"id": 65, "question": "Which of the following is a predominant evolutionary theory of phobias?", "options": ["Non-associative fear acquisition", "Learned fear responses", "Biological preparedness", "Specific phobia acquisition"], "correctAnswer": 2, "subject": "Psychopathology, Classification & Law", "subtopic": "", "difficulty": "", "explanation": "<p>Biological preparedness</p><p class=\"ex-why\"><b>Why:</b> Seligman’s biological preparedness (1971) says humans are evolutionarily ready to fear things that threatened our ancestors (snakes, heights), so these phobias form easily.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Non-associative fear acquisition — Non-associative accounts (Menzies &amp; Clarke) are a different theory, not the main evolutionary one.</li><li>(B) Learned fear responses — Learned fear (conditioning) is a learning account, not an evolutionary one.</li><li>(D) Specific phobia acquisition — ‘Specific phobia acquisition’ is not a theory name.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>This explains why phobias of guns or cars are rarer than of snakes.</li><li>Mowrer’s two-factor theory explains phobia maintenance.</li></ul>", "examWatch": "This is an actual previous-year question. Examiners do repeat questions, sometimes word for word — make sure you can answer it instantly."}, {"id": 66, "question": "Miss B tells her partner that she needs more appreciation. Which module of dialectical behaviour therapy is she working on?", "options": ["Mindfulness", "Emotion regulation", "Distress tolerance", "Interpersonal effectiveness"], "correctAnswer": 3, "subject": "Therapies & Interventions", "subtopic": "", "difficulty": "", "explanation": "<p>Interpersonal effectiveness</p><p class=\"ex-why\"><b>Why:</b> Asking a partner for what you need (more appreciation) is an interpersonal effectiveness skill in DBT (e.g. DEAR MAN).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Mindfulness — Mindfulness is about observing and describing the present moment.</li><li>(B) Emotion regulation — Emotion regulation is about understanding and changing emotions.</li><li>(C) Distress tolerance — Distress tolerance is about surviving crises without making things worse.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>DBT was developed by Marsha Linehan for borderline personality disorder.</li><li>DEAR MAN = Describe, Express, Assert, Reinforce, stay Mindful, Appear confident, Negotiate.</li></ul>", "examWatch": "A real past-paper question. Repeats are common, so learn it exactly as it is."}, {"id": 67, "question": "Which of the following is NOT a behaviour therapy technique?", "options": ["Flooding", "De-reflection", "Counterconditioning", "Systematic desensitisation"], "correctAnswer": 1, "subject": "Therapies & Interventions", "subtopic": "", "difficulty": "", "explanation": "<p>De-reflection</p><p class=\"ex-why\"><b>Why:</b> De-reflection is a logotherapy technique (Viktor Frankl), not a behaviour therapy technique.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Flooding — Flooding is a behaviour therapy technique.</li><li>(C) Counterconditioning — Counterconditioning is a behaviour therapy technique.</li><li>(D) Systematic desensitisation — Systematic desensitisation (Wolpe) is a behaviour therapy technique.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Frankl’s other technique: paradoxical intention.</li><li>Wolpe based systematic desensitisation on reciprocal inhibition.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this exact question has come before. Make sure you never lose this mark."}, {"id": 68, "question": "Which statement correctly describes the general findings of studies on the treatment of childhood anxiety?", "options": ["CBT and sertraline are not significantly different in terms of efficacy", "CBT improves outcome in around 60% of cases", "CBT and sertraline combined produce the best outcome", "All of these"], "correctAnswer": 3, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>All of these</p><p class=\"ex-why\"><b>Why:</b> The CAMS trial (Walkup and colleagues, 2008) found CBT alone (about 60% improved) and sertraline alone gave similar results, while the combination worked best (about 81%). So all three statements are true.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) CBT and sertraline are not significantly different in terms of efficacy — A is true, but B and C are also true.</li><li>(B) CBT improves outcome in around 60% of cases — B is true, but A and C are also true.</li><li>(C) CBT and sertraline combined produce the best outcome — C is true, but A and B are also true.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>CAMS = Child/Adolescent Anxiety Multimodal Study.</li><li>CBT is the first-line treatment for childhood anxiety.</li></ul>", "examWatch": "This is an actual previous-year question. Examiners do repeat questions, sometimes word for word — make sure you can answer it instantly."}, {"id": 69, "question": "Which of the following is NOT a core condition in Rogers&#x27; person-centred therapy?", "options": ["Unconditional positive regard", "Interpretation", "Empathy", "Congruence"], "correctAnswer": 1, "subject": "Therapies & Interventions", "subtopic": "", "difficulty": "", "explanation": "<p>Interpretation</p><p class=\"ex-why\"><b>Why:</b> Rogers’ three core conditions are unconditional positive regard, empathy and congruence (genuineness). Interpretation is a psychoanalytic technique.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Unconditional positive regard — Unconditional positive regard is a core condition.</li><li>(C) Empathy — Empathy is a core condition.</li><li>(D) Congruence — Congruence is a core condition.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Rogers listed six ‘necessary and sufficient’ conditions in 1957.</li><li>Person-centred therapy is non-directive.</li></ul>", "examWatch": "Not asked directly yet, but it sits right next to frequently asked topics — it may appear in a new form."}, {"id": 70, "question": "In Ellis&#x27;s ABC model of REBT, &#x27;B&#x27; stands for:", "options": ["Beliefs", "Behaviour", "Biology", "Bias"], "correctAnswer": 0, "subject": "Therapies & Interventions", "subtopic": "", "difficulty": "", "explanation": "<p>Beliefs</p><p class=\"ex-why\"><b>Why:</b> In Albert Ellis’s ABC model, A = Activating event, B = Beliefs (especially irrational ones), C = Consequences. Therapy adds D (Disputing) and E (Effective new beliefs).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Behaviour — Behaviour is the consequence, not B.</li><li>(C) Biology — Biology is not part of the model.</li><li>(D) Bias — Bias is not part of the model.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Ellis developed REBT in 1955.</li><li>Irrational ‘musts’ — Ellis called this ‘musturbation’.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a likely new area. Learn the key points above."}, {"id": 71, "question": "&quot;Wise mind&quot; is a skill taught in which DBT module?", "options": ["Interpersonal effectiveness", "Distress tolerance", "Mindfulness", "Emotion regulation"], "correctAnswer": 2, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Mindfulness</p><p class=\"ex-why\"><b>Why:</b> ‘Wise mind’ — the balance of emotion mind and reasonable mind — is a core mindfulness skill in DBT.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Interpersonal effectiveness — Interpersonal effectiveness is about asking for needs and saying no.</li><li>(B) Distress tolerance — Distress tolerance is about surviving crises.</li><li>(D) Emotion regulation — Emotion regulation is about changing emotions.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Mindfulness ‘what’ skills: observe, describe, participate; ‘how’ skills: non-judgementally, one-mindfully, effectively.</li><li>DBT is a third-wave therapy.</li></ul>", "examWatch": "A fresh, predicted question. The neighbouring topics are asked often, so it is worth knowing."}, {"id": 72, "question": "Cognitive defusion is a core process in:", "options": ["Psychoanalysis", "Acceptance and Commitment Therapy", "REBT", "Classical Beckian CBT"], "correctAnswer": 1, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Acceptance and Commitment Therapy</p><p class=\"ex-why\"><b>Why:</b> Cognitive defusion — seeing thoughts as just thoughts, not literal truths — is one of the six core processes of ACT (Steven Hayes).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Psychoanalysis — Psychoanalysis uses free association and interpretation.</li><li>(C) REBT — REBT disputes irrational beliefs.</li><li>(D) Classical Beckian CBT — Beck’s CBT tests and changes the content of thoughts.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>ACT hexaflex: acceptance, defusion, present moment, self-as-context, values, committed action.</li><li>ACT is based on relational frame theory.</li></ul>", "examWatch": "This angle is new, but the topic around it is popular with examiners — don’t skip it."}, {"id": 73, "question": "The Y-BOCS is used to rate the severity of:", "options": ["PTSD", "Obsessive-compulsive disorder", "Major depression", "Schizophrenia"], "correctAnswer": 1, "subject": "Assessment & Psychometrics", "subtopic": "", "difficulty": "", "explanation": "<p>Obsessive-compulsive disorder</p><p class=\"ex-why\"><b>Why:</b> The Yale-Brown Obsessive Compulsive Scale (Goodman and colleagues, 1989) rates the severity of obsessions and compulsions.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) PTSD — PTSD is rated with tools such as the CAPS.</li><li>(C) Major depression — Depression is rated with the HAM-D or BDI.</li><li>(D) Schizophrenia — Schizophrenia is rated with the PANSS or BPRS.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Y-BOCS has 10 core items scored 0–40.</li><li>CY-BOCS is the children’s version.</li></ul>", "examWatch": "Not asked directly yet, but it sits right next to frequently asked topics — it may appear in a new form."}, {"id": 74, "question": "Which rating scale is specifically designed to assess positive, negative and general psychopathology in schizophrenia?", "options": ["HAM-D", "Y-BOCS", "PANSS", "BDI"], "correctAnswer": 2, "subject": "Psychopathology, Classification & Law", "subtopic": "", "difficulty": "", "explanation": "<p>PANSS</p><p class=\"ex-why\"><b>Why:</b> The PANSS (Kay, Fiszbein and Opler, 1987) has 30 items rating positive symptoms, negative symptoms and general psychopathology in schizophrenia.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) HAM-D — HAM-D rates depression.</li><li>(B) Y-BOCS — Y-BOCS rates OCD.</li><li>(D) BDI — BDI is a self-report depression scale.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>PANSS subscales: positive (7), negative (7), general (16).</li><li>SAPS and SANS (Andreasen) are other symptom scales.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a likely new area. Learn the key points above."}, {"id": 75, "question": "The transtheoretical model (stages) of change was proposed by:", "options": ["Prochaska & DiClemente", "Dollard & Miller", "Abraham Maslow", "Carl Jung"], "correctAnswer": 0, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Prochaska &amp; DiClemente</p><p class=\"ex-why\"><b>Why:</b> Prochaska and DiClemente developed the transtheoretical (stages of change) model: precontemplation, contemplation, preparation, action, maintenance.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Dollard &amp; Miller — Dollard and Miller translated psychoanalysis into learning theory.</li><li>(C) Abraham Maslow — Maslow proposed the hierarchy of needs.</li><li>(D) Carl Jung — Jung proposed analytical psychology.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Motivational interviewing (Miller and Rollnick) is often matched to these stages.</li><li>Relapse is seen as part of the cycle.</li></ul>", "examWatch": "A real past-paper question. Repeats are common, so learn it exactly as it is."}, {"id": 76, "question": "<div class=\"ar-block\"><div class=\"ar-row\"><span class=\"ar-label\">Assertion (A)</span><span class=\"ar-text\">Flooding exposes the client gradually to a graded fear hierarchy.</span></div><div class=\"ar-row\"><span class=\"ar-label\">Reason (R)</span><span class=\"ar-text\">Systematic desensitization pairs relaxation with graded exposure through a fear hierarchy.</span></div></div>", "options": ["Both A and R are true and R is the correct explanation of A.", "Both A and R are true but R is not the correct explanation of A.", "A is true but R is false.", "A is false but R is true."], "correctAnswer": 3, "subject": "Therapies & Interventions", "subtopic": "", "difficulty": "", "explanation": "<p>A is false but R is true.</p><p class=\"ex-why\"><b>Why:</b> A is false: flooding exposes the person immediately to the most feared situation, with no graded hierarchy. R is true: systematic desensitisation (Wolpe) pairs relaxation with a graded hierarchy.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Both A and R are true and R is the correct explanation of A. — A is wrong because A is false.</li><li>(B) Both A and R are true but R is not the correct explanation of A. — B is wrong because A is false.</li><li>(C) A is true but R is false. — C is wrong because A is false and R is true.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Implosive therapy (Stampfl) is flooding in imagination.</li><li>Both methods work through extinction or habituation of fear.</li></ul>", "examWatch": "A fresh, predicted question. The neighbouring topics are asked often, so it is worth knowing."}, {"id": 77, "question": "People are less likely to help in an emergency when there are many witnesses. This phenomenon is called:", "options": ["Social influence", "Diffusion of responsibility", "Negative state relief", "Altruism"], "correctAnswer": 1, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Diffusion of responsibility</p><p class=\"ex-why\"><b>Why:</b> Diffusion of responsibility (Latané and Darley, 1968) means that with more bystanders, each person feels less responsible to help — the bystander effect.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Social influence — Social influence is a broad term, not this specific effect.</li><li>(C) Negative state relief — Negative state relief is helping to relieve one’s own bad mood.</li><li>(D) Altruism — Altruism is helping without expecting reward.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The study followed the Kitty Genovese case (1964).</li><li>Five-step model of helping: notice, interpret, take responsibility, decide how, act.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this exact question has come before. Make sure you never lose this mark."}, {"id": 78, "question": "A salesperson asks you to buy an expensive new refrigerator. When you refuse, he asks you to buy a portable ice box, and you feel obliged to comply. The technique used is:", "options": ["Low ball technique", "Foot-in-the-door technique", "Door-in-the-face technique", "Reciprocity"], "correctAnswer": 2, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Door-in-the-face technique</p><p class=\"ex-why\"><b>Why:</b> Door-in-the-face: make a large request that is refused, then a smaller one, which now seems reasonable.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Low ball technique — Low-ball: get agreement, then raise the cost.</li><li>(B) Foot-in-the-door technique — Foot-in-the-door: start with a small request, then a larger one.</li><li>(D) Reciprocity — Reciprocity is the general norm behind it, not the technique’s name.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Cialdini studied these compliance techniques.</li><li>Other techniques: that’s-not-all, scarcity.</li></ul>", "examWatch": "This is an actual previous-year question. Examiners do repeat questions, sometimes word for word — make sure you can answer it instantly."}, {"id": 79, "question": "Who is regarded as the Father of Experimental Psychology?", "options": ["William James", "Gustav Theodor Fechner", "Wilhelm Maximilian Wundt", "Sigmund Freud"], "correctAnswer": 2, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Wilhelm Maximilian Wundt</p><p class=\"ex-why\"><b>Why:</b> Wilhelm Wundt founded the first psychology laboratory at Leipzig in 1879, so he is called the father of experimental psychology.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) William James — William James is the father of American psychology (functionalism).</li><li>(B) Gustav Theodor Fechner — Fechner founded psychophysics.</li><li>(D) Sigmund Freud — Freud founded psychoanalysis.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Wundt used introspection; his school is called structuralism (via Titchener).</li><li>Ebbinghaus pioneered experimental study of memory.</li></ul>", "examWatch": "A real past-paper question. Repeats are common, so learn it exactly as it is."}, {"id": 80, "question": "Fritz Heider&#x27;s contribution to the study of attitudes is the:", "options": ["Cognitive Dissonance theory", "Self-Perception theory", "Balance theory", "Persuasion theory"], "correctAnswer": 2, "subject": "Social, Positive & Indian Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Balance theory</p><p class=\"ex-why\"><b>Why:</b> Fritz Heider’s balance theory (P-O-X model) says people want consistency among their attitudes towards a person and an object.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Cognitive Dissonance theory — Cognitive dissonance theory is Festinger’s.</li><li>(B) Self-Perception theory — Self-perception theory is Bem’s.</li><li>(D) Persuasion theory — Persuasion theories include Hovland’s Yale approach.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Heider also founded attribution theory (1958).</li><li>Osgood’s congruity theory is another consistency theory.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this exact question has come before. Make sure you never lose this mark."}, {"id": 81, "question": "The multitrait–multimethod matrix design is used to analyse:", "options": ["Concurrent validity", "Predictive validity", "Convergent validity", "Contact validity"], "correctAnswer": 2, "subject": "Core Psychological Processes", "subtopic": "", "difficulty": "", "explanation": "<p>Convergent validity</p><p class=\"ex-why\"><b>Why:</b> The multitrait–multimethod matrix (Campbell and Fiske, 1959) checks construct validity through convergent validity (different methods agree on the same trait) and discriminant validity.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Concurrent validity — Concurrent validity is tested by correlating with a current criterion.</li><li>(B) Predictive validity — Predictive validity is tested against a future criterion.</li><li>(D) Contact validity — ‘Contact validity’ is not a real type.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Discriminant validity: measures of different traits should not correlate highly.</li><li>Construct validity was described by Cronbach and Meehl (1955).</li></ul>", "examWatch": "This is an actual previous-year question. Examiners do repeat questions, sometimes word for word — make sure you can answer it instantly."}, {"id": 82, "question": "In a 3 × 4 contingency table, the degrees of freedom for the chi-square test are:", "options": ["12", "9", "7", "6"], "correctAnswer": 3, "subject": "Research, Statistics & Ethics", "subtopic": "", "difficulty": "", "explanation": "<p>6</p><p class=\"ex-why\"><b>Why:</b> df for chi-square in a contingency table = (rows − 1) × (columns − 1) = (3 − 1) × (4 − 1) = 2 × 3 = 6.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) 12 — 12 is rows × columns.</li><li>(B) 9 — 9 is not the right calculation.</li><li>(C) 7 — 7 is not the right calculation.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>For a goodness-of-fit test, df = categories − 1.</li><li>Chi-square is a non-parametric test for frequency data.</li></ul>", "examWatch": "A real past-paper question. Repeats are common, so learn it exactly as it is."}, {"id": 83, "question": "When relevant subgroups of a population are randomly sampled in proportion to their size, the technique is:", "options": ["Random sample technique", "Stratified random sample technique", "Representative sample", "Cluster sample technique"], "correctAnswer": 1, "subject": "Research, Statistics & Ethics", "subtopic": "", "difficulty": "", "explanation": "<p>Stratified random sample technique</p><p class=\"ex-why\"><b>Why:</b> In stratified random sampling the population is divided into subgroups (strata), and each is sampled at random in proportion to its size.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Random sample technique — Simple random sampling does not divide the population first.</li><li>(C) Representative sample — ‘Representative sample’ is a goal, not a technique.</li><li>(D) Cluster sample technique — Cluster sampling selects whole groups at random.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Quota sampling is the non-random version.</li><li>Stratification improves precision when strata differ.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this exact question has come before. Make sure you never lose this mark."}, {"id": 84, "question": "A Type II error is made by the researcher when:", "options": ["The null hypothesis is true and it is rejected", "The null hypothesis is true and it is accepted", "The null hypothesis is false and it is accepted", "The null hypothesis is false and it is rejected"], "correctAnswer": 2, "subject": "Research, Statistics & Ethics", "subtopic": "", "difficulty": "", "explanation": "<p>The null hypothesis is false and it is accepted</p><p class=\"ex-why\"><b>Why:</b> A Type II (beta) error is failing to reject (accepting) a null hypothesis that is actually false — missing a real effect.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) The null hypothesis is true and it is rejected — Rejecting a true null is a Type I error.</li><li>(B) The null hypothesis is true and it is accepted — Accepting a true null is a correct decision.</li><li>(D) The null hypothesis is false and it is rejected — Rejecting a false null is a correct decision.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Power = 1 − β.</li><li>Larger samples reduce Type II errors.</li></ul>", "examWatch": "This is an actual previous-year question. Examiners do repeat questions, sometimes word for word — make sure you can answer it instantly."}, {"id": 85, "question": "In a normal distribution, what proportion of scores lies above a z-score of +1?", "options": ["50%", "16%", "25%", "10%"], "correctAnswer": 1, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>16%</p><p class=\"ex-why\"><b>Why:</b> In a normal curve, about 34% of scores lie between the mean and +1 SD, so above +1 SD lies about 50% − 34% = 16% (15.87%).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) 50% — 50% lies above the mean (z = 0).</li><li>(C) 25% — 25% is not the right value.</li><li>(D) 10% — 10% is not the right value.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>About 68% of scores lie within ±1 SD, 95% within ±2 SD, 99.7% within ±3 SD.</li><li>z = +2 cuts off about 2.3% above.</li></ul>", "examWatch": "A real past-paper question. Repeats are common, so learn it exactly as it is."}, {"id": 86, "question": "<div class=\"ar-block\"><div class=\"ar-row\"><span class=\"ar-label\">Assertion (A)</span><span class=\"ar-text\">Lowering the alpha level from 0.05 to 0.01 reduces the probability of a Type I error.</span></div><div class=\"ar-row\"><span class=\"ar-label\">Reason (R)</span><span class=\"ar-text\">A Type I error is the rejection of a true null hypothesis, and its probability is set by the alpha level.</span></div></div>", "options": ["Both A and R are true and R is the correct explanation of A.", "Both A and R are true but R is not the correct explanation of A.", "A is true but R is false.", "A is false but R is true."], "correctAnswer": 0, "subject": "Research, Statistics & Ethics", "subtopic": "", "difficulty": "", "explanation": "<p>Both A and R are true and R is the correct explanation of A.</p><p class=\"ex-why\"><b>Why:</b> Both are true, and R explains A. Alpha is the chance of a Type I error, so lowering alpha from .05 to .01 lowers that chance.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Both A and R are true but R is not the correct explanation of A. — B is wrong because R does explain A.</li><li>(C) A is true but R is false. — C is wrong because R is true.</li><li>(D) A is false but R is true. — D is wrong because A is true.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Lowering alpha raises the risk of a Type II error.</li><li>Bonferroni correction lowers alpha for multiple tests.</li></ul>", "examWatch": "As per PsychLogic’s thorough analysis, this concept has been asked before in different forms — revise the related points as well."}, {"id": 87, "question": "A test has a reliability coefficient of 0.91 and a standard deviation of 15. The standard error of measurement is:", "options": ["2.25", "4.50", "1.35", "9.00"], "correctAnswer": 1, "subject": "Assessment & Psychometrics", "subtopic": "", "difficulty": "", "explanation": "<p>4.50</p><p class=\"ex-why\"><b>Why:</b> SEM = SD × √(1 − r) = 15 × √(1 − 0.91) = 15 × √0.09 = 15 × 0.3 = 4.5.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) 2.25 — 2.25 comes from a calculation error.</li><li>(C) 1.35 — 1.35 is SD × (1 − r).</li><li>(D) 9.00 — 9.00 is not the right calculation.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>95% confidence band ≈ obtained score ± 1.96 SEM.</li><li>Higher reliability means smaller SEM.</li></ul>", "examWatch": "This angle is new, but the topic around it is popular with examiners — don’t skip it."}, {"id": 88, "question": "Cohen&#x27;s kappa is used to estimate:", "options": ["Test–retest stability", "Criterion validity", "Inter-rater agreement corrected for chance", "Internal consistency of Likert scales"], "correctAnswer": 2, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Inter-rater agreement corrected for chance</p><p class=\"ex-why\"><b>Why:</b> Cohen’s kappa (1960) measures agreement between two raters on categories, corrected for the agreement expected by chance.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Test–retest stability — Test–retest stability is measured by correlating scores at two times.</li><li>(B) Criterion validity — Criterion validity is measured by correlating with an outside criterion.</li><li>(D) Internal consistency of Likert scales — Internal consistency is measured by Cronbach’s alpha.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Fleiss’ kappa is used for more than two raters.</li><li>Intraclass correlation is used for continuous ratings.</li></ul>", "examWatch": "Not asked directly yet, but it sits right next to frequently asked topics — it may appear in a new form."}, {"id": 89, "question": "On the WAIS-IV (mean 100, SD 15), a full-scale IQ of 130 corresponds approximately to the:", "options": ["98th percentile", "84th percentile", "99.9th percentile", "91st percentile"], "correctAnswer": 0, "subject": "Assessment & Psychometrics", "subtopic": "", "difficulty": "", "explanation": "<p>98th percentile</p><p class=\"ex-why\"><b>Why:</b> An IQ of 130 is 2 SD above the mean (100 + 2 × 15). About 97.7% of people score below it, so it is about the 98th percentile.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) 84th percentile — The 84th percentile is +1 SD (IQ 115).</li><li>(C) 99.9th percentile — The 99.9th percentile is about +3 SD (IQ 145).</li><li>(D) 91st percentile — The 91st percentile is about +1.33 SD (IQ 120).</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>IQ 70 (−2 SD) is about the 2nd percentile.</li><li>Wechsler introduced the deviation IQ.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a likely new area. Learn the key points above."}, {"id": 90, "question": "To compare the mean scores of three independent groups on one continuous variable, the appropriate test is:", "options": ["Chi-square", "z-test", "Paired t-test", "One-way ANOVA"], "correctAnswer": 3, "subject": "Research, Statistics & Ethics", "subtopic": "", "difficulty": "", "explanation": "<p>One-way ANOVA</p><p class=\"ex-why\"><b>Why:</b> One-way ANOVA compares the means of three or more independent groups on one continuous dependent variable.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Chi-square — Chi-square is for frequency (categorical) data.</li><li>(B) z-test — A z-test compares one or two means with known population SD.</li><li>(C) Paired t-test — A paired t-test compares two related means.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>ANOVA was developed by R.A. Fisher.</li><li>Post-hoc tests (Tukey, Scheffé) show which groups differ.</li></ul>", "examWatch": "A fresh, predicted question. The neighbouring topics are asked often, so it is worth knowing."}, {"id": 91, "question": "The non-parametric alternative to the independent-samples t-test is:", "options": ["Kruskal–Wallis test", "Wilcoxon signed-rank test", "Mann–Whitney U test", "Friedman test"], "correctAnswer": 2, "subject": "Research, Statistics & Ethics", "subtopic": "", "difficulty": "", "explanation": "<p>Mann–Whitney U test</p><p class=\"ex-why\"><b>Why:</b> The Mann–Whitney U test is the non-parametric version of the independent-samples t-test. It compares ranks of two independent groups.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Kruskal–Wallis test — Kruskal–Wallis is the non-parametric version of one-way ANOVA (three or more groups).</li><li>(B) Wilcoxon signed-rank test — Wilcoxon signed-rank is for two related samples.</li><li>(D) Friedman test — Friedman is for repeated measures across three or more conditions.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Non-parametric tests are used for ordinal data or when normality fails.</li><li>Spearman’s rho is the non-parametric correlation.</li></ul>", "examWatch": "This angle is new, but the topic around it is popular with examiners — don’t skip it."}, {"id": 92, "question": "By convention, a Cohen&#x27;s d of 0.80 represents a:", "options": ["Small effect", "Large effect", "Negligible effect", "Medium effect"], "correctAnswer": 1, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Large effect</p><p class=\"ex-why\"><b>Why:</b> Cohen’s conventions for d: 0.2 = small, 0.5 = medium, 0.8 = large.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Small effect — Small is about 0.2.</li><li>(C) Negligible effect — Negligible is below about 0.2.</li><li>(D) Medium effect — Medium is about 0.5.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Effect size shows how big a difference is, unlike p-values.</li><li>Eta squared and r are other effect sizes.</li></ul>", "examWatch": "Not asked directly yet, but it sits right next to frequently asked topics — it may appear in a new form."}, {"id": 93, "question": "Kaiser&#x27;s criterion retains factors with an eigenvalue greater than:", "options": ["1.0", "2.0", "1.5", "0.5"], "correctAnswer": 0, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>1.0</p><p class=\"ex-why\"><b>Why:</b> Kaiser’s (Kaiser–Guttman) criterion keeps factors with eigenvalues greater than 1.0, i.e. factors that explain more variance than a single variable.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) 2.0 — 2.0 is not the rule.</li><li>(C) 1.5 — 1.5 is not the rule.</li><li>(D) 0.5 — 0.5 is not the rule.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Cattell’s scree test is another method.</li><li>Parallel analysis is considered more accurate.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a likely new area. Learn the key points above."}, {"id": 94, "question": "Which of the following is NOT a specification of the POCSO Act, 2012?", "options": ["Recording the statement of the child at the residence of the child or at the place of his choice", "Police officer to not be in uniform while recording the statement of the child", "No aggressive questioning or character assassination of the child", "The child can be detained in the police station in the night"], "correctAnswer": 3, "subject": "Psychopathology, Classification & Law", "subtopic": "", "difficulty": "", "explanation": "<p>The child can be detained in the police station in the night</p><p class=\"ex-why\"><b>Why:</b> Under POCSO, a child cannot be detained at a police station at night for any reason. Recording at the child’s home, police not in uniform and no aggressive questioning are all required.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Recording the statement of the child at the residence of the child or at the place of his choice — Recording at the child’s residence is a POCSO provision.</li><li>(B) Police officer to not be in uniform while recording the statement of the child — Police not in uniform is a POCSO provision.</li><li>(C) No aggressive questioning or character assassination of the child — No aggressive questioning is a POCSO provision.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>POCSO Act, 2012 defines a child as below 18 years.</li><li>Special Courts try POCSO cases.</li></ul><p class=\"ex-why\" style=\"margin-top:14px\"><b>Exam note:</b> Exams like IHBAS, JEMAS and RINPAS have asked about mental health laws, RCI and disability Acts — usually one simple question per paper — while NIMHANS and CIP rarely ask them. Keep the basics of MHCA 2017, the RCI Act and the RPwD Act ready.</p>", "examWatch": "As per PsychLogic’s analysis, this exact question has come before. Make sure you never lose this mark."}, {"id": 95, "question": "Under the Mental Healthcare Act, 2017 (India), a person who attempts suicide is:", "options": ["Presumed to be under severe stress and not punishable", "Always treated as a cognizable offender", "Liable to imprisonment up to one year", "Punishable only on a repeat attempt"], "correctAnswer": 0, "subject": "Psychopathology, Classification & Law", "subtopic": "", "difficulty": "", "explanation": "<p>Presumed to be under severe stress and not punishable</p><p class=\"ex-why\"><b>Why:</b> Section 115 of MHCA 2017 presumes that a person who attempts suicide is under severe stress unless proved otherwise, and shall not be tried or punished. The government must provide care and rehabilitation.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) Always treated as a cognizable offender — It is not treated as a cognizable offence.</li><li>(C) Liable to imprisonment up to one year — There is no imprisonment.</li><li>(D) Punishable only on a repeat attempt — There is no punishment for repeat attempts.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>MHCA 2017 came into force on 29 May 2018.</li><li>Section 18: right to access mental healthcare.</li></ul><p class=\"ex-why\" style=\"margin-top:14px\"><b>Exam note:</b> Exams like IHBAS, JEMAS and RINPAS have asked about mental health laws, RCI and disability Acts — usually one simple question per paper — while NIMHANS and CIP rarely ask them. Keep the basics of MHCA 2017, the RCI Act and the RPwD Act ready.</p>", "examWatch": "A fresh, predicted question. The neighbouring topics are asked often, so it is worth knowing."}, {"id": 96, "question": "The Rights of Persons with Disabilities Act, 2016 recognises how many categories of disability?", "options": ["21", "14", "7", "25"], "correctAnswer": 0, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>21</p><p class=\"ex-why\"><b>Why:</b> The RPwD Act, 2016 recognises 21 specified disabilities, up from 7 in the PwD Act, 1995.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(B) 14 — 14 is not the number.</li><li>(C) 7 — 7 was the number in the 1995 Act.</li><li>(D) 25 — 25 is not the number.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>New categories include autism, specific learning disabilities, acid attack victims and thalassaemia.</li><li>Job reservation was raised from 3% to 4%.</li></ul><p class=\"ex-why\" style=\"margin-top:14px\"><b>Exam note:</b> Exams like IHBAS, JEMAS and RINPAS have asked about mental health laws, RCI and disability Acts — usually one simple question per paper — while NIMHANS and CIP rarely ask them. Keep the basics of MHCA 2017, the RCI Act and the RPwD Act ready.</p>", "examWatch": "This angle is new, but the topic around it is popular with examiners — don’t skip it."}, {"id": 97, "question": "The statutory body that maintains the Central Rehabilitation Register of clinical/rehabilitation psychologists in India is:", "options": ["ICMR", "NIMHANS", "NMC", "RCI"], "correctAnswer": 3, "subject": "General Clinical Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>RCI</p><p class=\"ex-why\"><b>Why:</b> The Rehabilitation Council of India (RCI), under the RCI Act 1992, regulates training and maintains the Central Rehabilitation Register. Clinical psychologists must be registered with it.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) ICMR — ICMR funds and regulates medical research.</li><li>(B) NIMHANS — NIMHANS is a training and research institute.</li><li>(C) NMC — NMC regulates medical education and doctors.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The RCI Act was amended in 2000.</li><li>Practising without RCI registration is an offence.</li></ul><p class=\"ex-why\" style=\"margin-top:14px\"><b>Exam note:</b> Exams like IHBAS, JEMAS and RINPAS have asked about mental health laws, RCI and disability Acts — usually one simple question per paper — while NIMHANS and CIP rarely ask them. Keep the basics of MHCA 2017, the RCI Act and the RPwD Act ready.</p>", "examWatch": "Not asked directly yet, but it sits right next to frequently asked topics — it may appear in a new form."}, {"id": 98, "question": "The &#x27;Big Five&#x27; model of personality does NOT include which of the following traits?", "options": ["Openness to experience", "Neuroticism", "Intuition", "Agreeableness"], "correctAnswer": 2, "subject": "Core Psychological Processes", "subtopic": "", "difficulty": "", "explanation": "<p>Intuition</p><p class=\"ex-why\"><b>Why:</b> The Big Five (OCEAN) traits are Openness, Conscientiousness, Extraversion, Agreeableness and Neuroticism. Intuition is from the MBTI (sensing–intuition), not the Big Five.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Openness to experience — Openness to experience is a Big Five trait.</li><li>(B) Neuroticism — Neuroticism is a Big Five trait.</li><li>(D) Agreeableness — Agreeableness is a Big Five trait.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Costa and McCrae’s NEO-PI-R measures the Big Five.</li><li>Goldberg used the lexical approach.</li></ul>", "examWatch": "Asked in earlier papers; examiners like to test it through a case or a NOT question."}, {"id": 99, "question": "In Kohlberg&#x27;s theory, the stage at which an individual develops their own moral guidelines, which may or may not always fit the law, is characterized by:", "options": ["Maintaining social order", "Individualism and Exchange", "Obedience and punishment orientation", "Universal Principles"], "correctAnswer": 3, "subject": "Development, Child & Adolescent", "subtopic": "", "difficulty": "", "explanation": "<p>Universal Principles</p><p class=\"ex-why\"><b>Why:</b> Kohlberg’s Stage 6 (universal ethical principles, postconventional level) is when people follow their own principles of justice and rights, even if these conflict with the law.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Maintaining social order — Maintaining social order is Stage 4 (conventional).</li><li>(B) Individualism and Exchange — Individualism and exchange is Stage 2 (preconventional).</li><li>(C) Obedience and punishment orientation — Obedience and punishment is Stage 1 (preconventional).</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Stage 5 is social contract and individual rights.</li><li>Few adults reach Stage 6 consistently.</li></ul>", "examWatch": "This is an actual previous-year question. Examiners do repeat questions, sometimes word for word — make sure you can answer it instantly."}, {"id": 100, "question": "Which of the following is NOT a component of Seligman&#x27;s PERMA model of well-being?", "options": ["Meaning", "Relationships", "Engagement", "Resilience"], "correctAnswer": 3, "subject": "Social, Positive & Indian Psychology", "subtopic": "", "difficulty": "", "explanation": "<p>Resilience</p><p class=\"ex-why\"><b>Why:</b> Seligman’s PERMA model (2011): Positive emotion, Engagement, Relationships, Meaning, Accomplishment. Resilience is not one of the five.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>(A) Meaning — Meaning is a PERMA element.</li><li>(B) Relationships — Relationships is a PERMA element.</li><li>(C) Engagement — Engagement is a PERMA element.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Seligman’s book Flourish (2011) introduced PERMA.</li><li>Engagement links to Csikszentmihalyi’s ‘flow’.</li></ul>", "examWatch": "As per PsychLogic’s analysis, this is a likely new area. Learn the key points above."}];
